            "codex:custom_pet"
        );
        // 未限定 id（预设宠物，安全字符集）与来源限定 id 都是合法激活选择；
        // 只有非法字符集 / 未知来源限定才回落到默认预设（同样是可渲染的宠物）。
        assert_eq!(normalize_active_pet(Some("cat"), DEFAULT), "cat");
