        for legacy_or_invalid in ["other:pet", "chat:../pet", "bad id", "x/y"] {
            assert_eq!(
                normalize_active_pet(Some(legacy_or_invalid), DEFAULT),
                DEFAULT,
                "旧版或非法 id {legacy_or_invalid} 应回落到默认预设"
            );
        }
    }

