            (
                "image/webp",
                SpriteGrid {
                    version: PET_SPRITE_V2,
                    columns: 8,
                    rows: 11
                }
            ),
            "88x88 同时整除 8 与 11，缺省取 v2"
        );

        // 高度只整除 9：8x9 的旧版图集必须按 v1 接受，而不是要求 11 行。
        let mut v1 = valid.clone();
        v1[27..30].copy_from_slice(&[89, 0, 0]);
        assert_eq!(
            spritesheet_dimensions(&v1, None).unwrap().1,
