        // 且用户常把 `~/.codex/pets` 整体压缩（宠物目录外还有包装目录）。
        let manifest = br#"{"id":"jiaran","displayName":"Jiaran","spriteVersionNumber":1,"spritesheetPath":"spritesheet.webp"}"#;
        let mut webp = valid_test_webp();
