// configure tauri builder
pub fn builder() -> tauri::Builder<tauri::Wry> {
    let mut builder = tauri::Builder::default();

    // E2E：内嵌 WebDriver server 只在 E2E 进程装配（`@wdio/tauri-service` 拉起应用时注入
    // TAURI_WEBDRIVER_PORT）。插件一旦注册就会无条件监听 127.0.0.1:4445，并接管每个 webview
    // 的 script dialog（默认弹窗被禁用，转成等 WebDriver 应答、最长 30s 的 pending alert）；
    // 正常 dev/release 会话既不该开这个端口，也不该动用户的弹窗与文件选择。
    if crate::config::is_e2e_run() {
        builder = builder.plugin(tauri_plugin_wdio_webdriver::init());
    }

    let builder = builder
        .manage(crate::desktop::pet_mouse::PetMouseStreamState::default())
        .setup(|app| {
            let app_handle = app.handle().clone();
            // 首装检测必须最先执行：窗口几何恢复/退出保存等任何 store 写入都会
            // 创建 store 文件，判定晚于它们会把首装误判为升级（见
            // config::detect_first_install 的时序说明）。
            crate::config::detect_first_install(&app_handle);
            build_main_window(&app_handle)?;
            #[cfg(target_os = "macos")]
            install_macos_menu(&app_handle)?;
            tray(&app_handle)?;
            // 桌宠窗口：按「是否启用」设置惰性创建/显示（幂等）。
            crate::desktop::pet::init_pet_window(&app_handle);
            setup(app_handle.clone());
            // 方案 1（host → rust → pet）：Rust 作为宿主会话增量 SSE 流的消费者，
            // 不再依赖 iframe 的 invoke 桥转发（#396 根因）。断连自动重连；
            // 仅当桌宠已启用且可见才订阅——关闭桌宠则宿主不做任何转发。
            crate::bridge::pet::sync_pet_session_stream(
                &app_handle,
                crate::bridge::pet::pet_stream_wanted(&app_handle),
            );
            Ok(())
        })
        .on_menu_event(|app, event| match event.id().as_ref() {
            "desktop-toggle-sidebar"
            | "desktop-toggle-right-panel"
            | "desktop-open-terminal"
            | "desktop-search-chats"
            | "desktop-zoom-in"
            | "desktop-zoom-out"
            | "desktop-zoom-reset"
            | "desktop-task-manager" => {
                if let Some(window) = app.webview_windows().into_values().find(|window| {
                    window.label() != crate::desktop::pet::PET_WINDOW_LABEL
                        && window.is_focused().unwrap_or(false)
                }) {
                    if let Err(error) =
                        app.emit_to(window.label(), "macos-menu-action", event.id().as_ref())
                    {
                        log::warn!("[menu] failed to emit View action: {error}");
                    }
                }
            }
            #[cfg(target_os = "macos")]
            "desktop-fullscreen" => {
                if let Some(window) = app.webview_windows().into_values().find(|window| {
                    window.label() != crate::desktop::pet::PET_WINDOW_LABEL
                        && window.is_focused().unwrap_or(false)
                }) {
                    if let Err(error) = window
                        .is_fullscreen()
                        .and_then(|is_fullscreen| window.set_fullscreen(!is_fullscreen))
                    {
                        log::warn!("[menu] FULLSCREEN_TOGGLE_FAILED: {error}");
                    }
                }
            }
            "desktop-config"
            | "desktop-profiles"
            | "desktop-plugins"
            | "desktop-harness"
            | "desktop-about"
            | "desktop-copy-run-logs"
            | "desktop-check-update"
            | "desktop-restart"
            | "desktop-documentation"
            | "desktop-keyboard-shortcuts"
            | "desktop-new-window"
            | "desktop-new-chat"
            | "desktop-open-folder" => {
                if let Err(error) = app.emit("macos-menu-action", event.id().as_ref()) {
                    log::warn!("[menu] failed to emit macOS menu action: {error}");
                }
            }
            _ => {}
        })
        // 关闭行为由设置项 `setting.close_action` 控制（D-08 / D-09）：
        // - quit：关窗即完整退出进程，不驻留托盘、不切 Accessory；
        // - tray（默认）：阻止关闭，应用级 hide（Cmd+H 语义）并切 Accessory 隐藏 Dock。
        // 退出分支**故意不加** `#[cfg(target_os = "macos")]` 门控 —— 「关闭窗口＝
        // 退出应用」是用户可选项，语义上应当三平台一致，不是 macOS 专属；而
        // `activation::on_window_hidden` 仅在 macOS 上有实现，故它保留 macOS 门控。
        // 点击关闭按钮时按设置决定：隐藏到托盘驻留，还是完整退出程序
        .on_window_event(|window, event| match event {
            tauri::WindowEvent::CloseRequested { api, .. } => {
                if window.label() == crate::desktop::pet::PET_WINDOW_LABEL {
                    // 桌宠窗口没有装饰按钮，但 Alt+F4 / 系统关闭仍会走到这里：语义等同
                    // 「关闭宠物」——持久化 enabled=false 并销毁窗口（与会话流一起收口）。
                    // 走命令本身而不是内部函数：关闭是持久动作，重启后不该再自己起来。
                    api.prevent_close();
                    let handle = window.app_handle().clone();
                    if let Err(error) = crate::bridge::pet::set_pet_enabled(handle, false) {
                        log::warn!("[pet] PET_WINDOW_DESTROY_FAILED: {error}");
                    }
                    return;
                }
                // 主窗口以外的附加窗口（「文件 → 新建窗口」）不驻留托盘：直接关闭
                // 销毁。隐藏它们既没有恢复入口，也不符合「关掉这个窗口」的直觉。
                if window.label() != MAIN_WINDOW_LABEL {
                    return;
                }
                // get_store_dat_setting 内部已归一化，取值只可能是 tray 或 quit
                let close_action =
                    crate::config::get_store_dat_setting(window.app_handle()).close_action;
                if close_action == crate::config::CLOSE_ACTION_QUIT {
                    // 不 prevent_close、不 hide：直接退出。app.exit(0) 会走
                    // RunEvent::ExitRequested，既有的几何保存逻辑照常触发
                    window.app_handle().exit(0);
                    return;
                }
                api.prevent_close();
                // macOS 上隐藏不能用窗口级 orderOut（window.hide()）：应用隐藏
                // 最后一个窗口后会被系统在 ~1.5s 后发 quit Apple Event 终止
                // （macOS 26/27 对「无可见窗口」应用的回收行为）。正确顺序：
                // 先切 Accessory（此时窗口仍可见，避免 Accessory 下 show 的
                // tauri #5122 问题），再用应用级 hide（Cmd+H 语义）—— 系统不会
                // 回收 hide: 隐藏的应用。恢复路径见 utils::show_main_window 的
                // app.show()（unhide）配对。
                #[cfg(target_os = "macos")]
                {
                    crate::desktop::activation::on_window_hidden(window, &close_action);
                    if let Err(error) = window.app_handle().hide() {
                        // 应用级 hide 失败（理论不发生）时**保持窗口可见**：
                        // 窗口级 hide() 是 orderOut，会落入 macOS 26/27 对
                        // 「无可见窗口」应用的 ~1.5s quit 回收 —— 比可见窗口
                        // 更糟。可见窗口是严格更安全的降级态。
                        // 同时回退到 Regular 策略：on_window_hidden 已切到 Accessory，
                        // hide 失败意味着应用实际未隐藏，若不恢复 Regular 会丢失 Dock
                        // 与 Cmd-Tab 入口。
                        // hide 失败意味着应用仍停留在 Accessory（on_window_hidden
                        // 已提前切过去），可见窗口配合消失的 Dock/⌘-Tab 会让用户
                        // 无法将应用拉回前台，故这里必须切回 regular 恢复 Dock。
                        crate::desktop::activation::set_regular_policy(window.app_handle());
                        log::error!("[activation] APP_HIDE_FAILED: {error}");
                    }
                }
                #[cfg(not(target_os = "macos"))]
                let _ = window.hide();
            }
            tauri::WindowEvent::ScaleFactorChanged { .. } => {
                if window.label() == crate::desktop::pet::PET_WINDOW_LABEL {
                    crate::desktop::pet::apply_pet_size(window.app_handle());
                }
            }
            tauri::WindowEvent::Moved(_) | tauri::WindowEvent::Resized(_) => {
                match window.label() {
                    label if label == crate::desktop::pet::PET_WINDOW_LABEL => {
                        crate::desktop::pet::save_pet_window_geometry(window);
                    }
                    label if label == MAIN_WINDOW_LABEL => crate::config::save_geometry(window),
                    _ => {}
                }
                #[cfg(target_os = "macos")]
                {
                    if matches!(event, tauri::WindowEvent::Resized(_)) {
                        // 全屏文案跟随聚焦的壳层窗口，Accessory 切换仍只处理主窗口。
                        sync_macos_fullscreen_menu(window);
                        if window.label() == MAIN_WINDOW_LABEL {
                            // 退出全屏后补做全屏期间被推迟的 Accessory 切换。
                            crate::desktop::activation::on_window_resized(window);
                        }
                    }
                }
            }
            #[cfg(target_os = "macos")]
            tauri::WindowEvent::Focused(true) => sync_macos_fullscreen_menu(window),
            _ => {}
        });

    // 单例模式：多次双击图标（或重复启动）时不会新开窗口，而是把
    // 已存在的（可能已隐藏到托盘）主窗口调到前台，实现“单例 + 复用后台窗口”。
    // 该回调在首次启动时也会以当前进程的参数触发一次（幂等，仅 show/focus），
    // 之后每次二次启动都会派发到这里，重新展示后台运行的主窗口。
    // 仅在生产环境（release）启用：debug 开发调试时若启用单例，
    // 二次启动的调试进程会被吞掉（例如 tauri dev 多实例调试），
    // 因此开发环境跳过该插件。
    // `deep-link` feature 只在单例在场时起作用：把二次启动携带的 `dsh://` URL
    // （成功页「打开应用」按钮）转发给主实例派发 open-url。
    #[cfg(not(debug_assertions))]
    let builder = builder; // Managed identity owns the private OS file lock.

    // Windows/WebView2 上 wry 忽略 `for_main_frame_only`、把每个初始化脚本注入所有子 frame，
    // 而 Tauri 只在 main frame 定义 `window.__TAURI_INTERNALS__`；dsh GUI 所在的跨源 iframe
    // 因此每次加载都抛 `path` 插件脚本的 "reading 'plugins'"。垫片注册在最前面，保证排在
    // core 插件（path 在其中）之前执行，只补骨架、不碰 isTauri（见 desktop::tauri_internals）。
    #[cfg(windows)]
    let builder = builder.plugin(crate::desktop::tauri_internals::shim());

    let builder = builder
        // 官方跨平台登录启动实现：Windows HKCU Run、macOS LaunchAgent、Linux XDG。
        // Opener plugin
        .plugin(tauri_plugin_opener::init())
        // Notification plugin（官方插件）：权限查询等通用通知能力。

        // FS plugin
        .plugin(tauri_plugin_fs::init())
        // HTTP plugin：桌宠窗口拉取远端宠物素材时把 fetch 交给 Rust 发起，
        // 绕开 raw.githubusercontent.com 不返回 CORS 头导致的浏览器拦截。
        .plugin(tauri_plugin_http::init())
        // Simple Store plugin
        .plugin(tauri_plugin_store::Builder::new().build())
        // OS plugin：前端据此判断系统版本（macOS 10.15 没有 `WKWebView.pageZoom`，
        // 不能把缩放应用到 WebView），见 `hooks/use-zoom-factor.ts`。
        .plugin(tauri_plugin_os::init());

    // Notifications plugin（Choochmeque fork）：壳层发带交互按钮的通知，并通过
    // `onNotificationClicked` / `onAction` 收点击与按钮动作——官方插件在桌面端 `show()`
    // 之后即丢弃 handle，拿不到这两类事件。macOS 上它需要 Xcode 16+（Swift 6 typed throws），
    // CI 见 .github/workflows/ci.yml 的 `Select Xcode 16`。
    //
    // macOS 上它还要求进程跑在 `.app` 包内（`UNUserNotificationCenter` 的前置条件，见 vendor 的
    // `macos::validation::require_bundle`）：`tauri dev` 跑的是裸二进制，注册它会让插件初始化
    // 直接报错、整个应用起不来，所以未打包时跳过这条通路（打包后自动生效）。
    #[cfg(target_os = "macos")]
    let in_app_bundle = std::env::current_exe()
        .map(|exe| exe.to_string_lossy().contains(".app/Contents/MacOS/"))
        .unwrap_or(false);
    #[cfg(not(target_os = "macos"))]
    let in_app_bundle = true;
    let builder = if in_app_bundle && !crate::managed::enabled() {
        builder.plugin(tauri_plugin_notifications::init())
    } else {
        log::warn!(
            "未运行在 .app 包内，跳过 tauri-plugin-notifications：macOS 的系统通知需要 .app 包，\
             打包后自动生效"
        );
        builder
    };

    // `dsh://` 深链（成功页「打开应用」按钮）只在打包态启用：debug 注册会把系统
    // `dsh:` 指向调试产物，与官方 Electron 的 `app.isPackaged` 门禁一致。
    #[cfg(not(debug_assertions))]
    let builder = builder; // No global protocol registration.

    builder
}

#[cfg(windows)]
use tauri::Manager;

/// 如果 DSH 插件仍有兜底走浏览器 Notification，则保持“已授权”假象，
/// 并让每次 `new Notification(...)` 转成发给宿主窗口的 postMessage。
pub(crate) const NOTIFICATION_SHIM_JS: &str = r#"(function () {
  if (window.__dsh_native_notification_bridge__) return;
  window.__dsh_native_notification_bridge__ = true;

  var hostHidden = false;
  var pendingOnClicks = {};

  function setHostHidden(hidden) {
    hidden = !!hidden;
    if (hostHidden === hidden) return;
    hostHidden = hidden;
    try { document.dispatchEvent(new Event('visibilitychange')); } catch (_) {}
  }

  function send(message) {
    try {
      window.parent.postMessage(Object.assign({ source: 'dsh-notification-bridge' }, message), '*');
    } catch (_) {}
  }

  function sessionIdFromTag(tag) {
    var m = /^dsh-notification-(?:pending-)?(.+)-\d+$/.exec(tag || '');
    return m ? m[1] : '';
  }

  function DshNativeNotification(title, options) {
    options = options || {};
    this.title = String(title || '');
    this.options = options;
    this.tag = options.tag || '';
    this.onclick = null;
    this.onaction = null;
    this.onclose = null;
    this.onerror = null;
    this.onshow = null;

    if (this.tag) pendingOnClicks[this.tag] = this;

    send({
      type: 'dsh://native-notification',
      title: this.title,
      body: String(options.body || ''),
      tag: this.tag,
      requireInteraction: !!options.requireInteraction,
      silent: !!options.silent,
      sessionId: options.sessionId || sessionIdFromTag(this.tag),
      actions: Array.isArray(options.actions) ? options.actions : [],
      href: location.href,
      origin: location.origin
    });
  }

  DshNativeNotification.permission = 'granted';
  DshNativeNotification.requestPermission = function () {
    return Promise.resolve('granted');
  };
  DshNativeNotification.prototype.close = function () {
    if (!this.tag) return;
    // 关掉后不会再回灌点击：及时释放实例，避免 pendingOnClicks 无限增长。
    delete pendingOnClicks[this.tag];
    send({ type: 'dsh://close-notification', tag: this.tag });
  };

  window.Notification = DshNativeNotification;

  // 属性拦截：让 iframe 中的 visibilityState 强行跟随桌面宿主状态
  (function installHiddenOverrides() {
    var descMap = {
      hidden: { configurable: true, get: function () { return hostHidden; } },
      visibilityState: { configurable: true, get: function () { return hostHidden ? 'hidden' : 'visible'; } }
    };
    [document, Object.getPrototypeOf(document)].forEach(function (target) {
      if (!target) return;
      try {
        Object.defineProperty(target, 'hidden', descMap.hidden);
        Object.defineProperty(target, 'visibilityState', descMap.visibilityState);
      } catch (_) {}
    });
  })();

  // 宿主状态只认壳层推送（`dsh://visibility-state`）与「帧内拿到焦点」这一条正向证据。
  // 以前这里还有 `blur → 隐藏`，但帧失焦 ≠ 窗口隐藏：点壳层标题栏、设置面板都会让
  // 帧 blur，而窗口仍在前台；那条误判会让「仅在未聚焦时」在用户正盯着会话时弹通知。
  // 帧拿到焦点则窗口必然在前台（最小化的窗口给不了焦点），所以 focus 可以安全地纠正。
  window.addEventListener('focus', function () { setHostHidden(false); });

  // 查找并聚焦对应的 Session
  function tryFocusSession(sessionId, title) {
    if (!sessionId && !title) return;

    if (typeof window.__dsh_focusSession === 'function') {
      try { window.__dsh_focusSession(sessionId); return; } catch (_) {}
    }

    if (sessionId) {
      var el = document.querySelector('[data-session-id="' + sessionId + '"], [data-session="' + sessionId + '"], [data-id="' + sessionId + '"]');
      if (el) { el.click(); return; }
    }

    if (title) {
      var trimmedTitle = String(title).trim();
      var nodes = document.querySelectorAll('button, [role="button"], li, a');
      for (var i = 0; i < nodes.length; i++) {
        if (nodes[i].offsetParent !== null && nodes[i].textContent.trim() === trimmedTitle) {
          nodes[i].click();
          return;
        }
      }
    }
  }

  window.addEventListener('message', function (event) {
    var data = event.data;
    if (!data || typeof data !== 'object') return;

    switch (data.type) {
      case 'dsh://visibility-state':
        setHostHidden(data.hidden);
        break;
      case 'dsh://focus-session':
        tryFocusSession(data.sessionId, data.title);
        break;
      case 'dsh://notification-clicked':
        var instance = pendingOnClicks[data.tag];
        if (!instance) break;
        // 一次点击只回灌一次；用完即弃，避免长时间运行后字典持续增长。
        delete pendingOnClicks[data.tag];
        // 按钮点击走 onaction（动作 id 由前端约定），点通知本体走 onclick。
        // 带输入框的按钮（如「回复」）把用户填的文本一并回灌；没填时给空串。
        if (data.action && typeof instance.onaction === 'function') {
          var inputValue = typeof data.inputValue === 'string' ? data.inputValue : '';
          try { instance.onaction({ action: String(data.action), tag: data.tag, inputValue: inputValue }); } catch (_) {}
        } else if (typeof instance.onclick === 'function') {
          try { instance.onclick(new Event('click')); } catch (_) {}
        }
        break;
    }
  });
})();"#;

/// 在 Windows WebView2 中接管 iframe 内的通知请求并注入原生通知桥。
#[cfg(windows)]
pub fn enable_notification_permissions(
    webview: tauri::webview::PlatformWebview,
    parent: tauri::WebviewWindow<tauri::Wry>,
) -> Result<(), Box<dyn std::error::Error>> {
    if crate::managed::enabled() {return Ok(());}
    use rfd::{MessageButtons, MessageDialog, MessageDialogResult};
    use webview2_com::{
        ExecuteScriptCompletedHandler, FrameContentLoadingEventHandler, FrameCreatedEventHandler,
        FramePermissionRequestedEventHandler,
        Microsoft::Web::WebView2::Win32::{
            ICoreWebView2Frame3, ICoreWebView2Profile4, ICoreWebView2_13, ICoreWebView2_4,
            COREWEBVIEW2_PERMISSION_KIND, COREWEBVIEW2_PERMISSION_KIND_AUTOPLAY,
            COREWEBVIEW2_PERMISSION_KIND_CAMERA, COREWEBVIEW2_PERMISSION_KIND_CLIPBOARD_READ,
            COREWEBVIEW2_PERMISSION_KIND_FILE_READ_WRITE, COREWEBVIEW2_PERMISSION_KIND_GEOLOCATION,
            COREWEBVIEW2_PERMISSION_KIND_LOCAL_FONTS, COREWEBVIEW2_PERMISSION_KIND_MICROPHONE,
            COREWEBVIEW2_PERMISSION_KIND_MIDI_SYSTEM_EXCLUSIVE_MESSAGES,
            COREWEBVIEW2_PERMISSION_KIND_MULTIPLE_AUTOMATIC_DOWNLOADS,
            COREWEBVIEW2_PERMISSION_KIND_NOTIFICATIONS, COREWEBVIEW2_PERMISSION_KIND_OTHER_SENSORS,
            COREWEBVIEW2_PERMISSION_KIND_UNKNOWN_PERMISSION,
            COREWEBVIEW2_PERMISSION_KIND_WINDOW_MANAGEMENT, COREWEBVIEW2_PERMISSION_STATE_ALLOW,
            COREWEBVIEW2_PERMISSION_STATE_DEFAULT, COREWEBVIEW2_PERMISSION_STATE_DENY,
        },
        PermissionRequestedEventHandler, SetPermissionStateCompletedHandler,
    };
    use windows_core::{Interface, HSTRING};

    log::info!("[notification] registering WebView2 notification handlers");

    fn ask_notification_permission(parent: &tauri::WebviewWindow<tauri::Wry>) -> bool {
        MessageDialog::new()
            .set_parent(parent)
            .set_title("允许发送通知？")
            .set_description("DSH 页面请求发送桌面通知。是否允许？")
            .set_buttons(MessageButtons::YesNo)
            .show()
            == MessageDialogResult::Yes
    }

    fn notification_origins(parent: &tauri::WebviewWindow<tauri::Wry>) -> Vec<String> {
        let mut origins = vec![
            crate::config::get_dsh_service_url(crate::config::DSH_PORT),
            crate::config::get_dsh_service_url(crate::config::DSH_DEV_PORT),
        ];
        let store_port = crate::config::get_store_dat_setting(parent.app_handle()).port;
        let store_origin = crate::config::get_dsh_service_url(store_port);
        if !origins.contains(&store_origin) {
            origins.push(store_origin);
        }
        origins
    }

    fn permission_kinds() -> [COREWEBVIEW2_PERMISSION_KIND; 12] {
        [
            COREWEBVIEW2_PERMISSION_KIND_AUTOPLAY,
            COREWEBVIEW2_PERMISSION_KIND_CAMERA,
            COREWEBVIEW2_PERMISSION_KIND_CLIPBOARD_READ,
            COREWEBVIEW2_PERMISSION_KIND_FILE_READ_WRITE,
            COREWEBVIEW2_PERMISSION_KIND_GEOLOCATION,
            COREWEBVIEW2_PERMISSION_KIND_LOCAL_FONTS,
            COREWEBVIEW2_PERMISSION_KIND_MICROPHONE,
            COREWEBVIEW2_PERMISSION_KIND_MIDI_SYSTEM_EXCLUSIVE_MESSAGES,
            COREWEBVIEW2_PERMISSION_KIND_MULTIPLE_AUTOMATIC_DOWNLOADS,
            COREWEBVIEW2_PERMISSION_KIND_OTHER_SENSORS,
            COREWEBVIEW2_PERMISSION_KIND_WINDOW_MANAGEMENT,
            COREWEBVIEW2_PERMISSION_KIND_NOTIFICATIONS,
        ]
    }

    fn should_allow_permission(kind: COREWEBVIEW2_PERMISSION_KIND) -> bool {
        matches!(
            kind,
            COREWEBVIEW2_PERMISSION_KIND_AUTOPLAY
                | COREWEBVIEW2_PERMISSION_KIND_CAMERA
                | COREWEBVIEW2_PERMISSION_KIND_CLIPBOARD_READ
                | COREWEBVIEW2_PERMISSION_KIND_FILE_READ_WRITE
                | COREWEBVIEW2_PERMISSION_KIND_GEOLOCATION
                | COREWEBVIEW2_PERMISSION_KIND_LOCAL_FONTS
                | COREWEBVIEW2_PERMISSION_KIND_MICROPHONE
                | COREWEBVIEW2_PERMISSION_KIND_MIDI_SYSTEM_EXCLUSIVE_MESSAGES
                | COREWEBVIEW2_PERMISSION_KIND_MULTIPLE_AUTOMATIC_DOWNLOADS
                | COREWEBVIEW2_PERMISSION_KIND_OTHER_SENSORS
                | COREWEBVIEW2_PERMISSION_KIND_WINDOW_MANAGEMENT
        )
    }

    unsafe fn reset_persisted_notification_permissions(
        webview2: &webview2_com::Microsoft::Web::WebView2::Win32::ICoreWebView2,
        origins: &[String],
    ) -> Result<(), Box<dyn std::error::Error>> {
    if crate::managed::enabled() {return Ok(());}
        let webview13 = webview2.cast::<ICoreWebView2_13>()?;
        let profile = webview13.Profile()?;
        let Ok(profile4) = profile.cast::<ICoreWebView2Profile4>() else {
            log::warn!("[notification] ICoreWebView2Profile4 cast failed; skip reset.");
            return Ok(());
        };

        for origin in origins {
            // 每个 origin 要写 12 种 permission：逐个 INFO 会在一毫秒内刷出二十多行，
            // 把 desktop.log 真正有用的行挤走。正常路径只留一条 debug 汇总
            // （`RUST_LOG=debug` 可见），失败仍逐次告警。
            log::debug!("[permission] resetting persisted permissions for {origin}");
            for kind in permission_kinds() {
                let origin_str = origin.clone();
                let hstring = HSTRING::from(origin.as_str());
                // HSTRING 是引用计数类型，克隆只增加引用计数、共享底层缓冲区。
                // 回调（completed handler）是异步调用的，让克隆句柄随回调一起持有，
                // 避免 SetPermissionState 借用的句柄在回调存活期内失效。
                let hstring_for_callback = hstring.clone();
                let state = if kind == COREWEBVIEW2_PERMISSION_KIND_NOTIFICATIONS {
                    COREWEBVIEW2_PERMISSION_STATE_DEFAULT
                } else {
                    COREWEBVIEW2_PERMISSION_STATE_ALLOW
                };

                profile4.SetPermissionState(
                    kind,
                    &hstring,
                    state,
                    &SetPermissionStateCompletedHandler::create(Box::new(move |result| {
                        if let Err(e) = result {
                            log::warn!(
                                "[permission] failed to set permission for {origin_str}: {e}"
                            );
                        }
                        let _ = &hstring_for_callback;
                        Ok(())
                    })),
                )?;
            }
        }
        Ok(())
    }

    unsafe fn setup_frame_handlers(
        frame3: ICoreWebView2Frame3,
        parent: tauri::WebviewWindow<tauri::Wry>,
    ) {
        let parent_for_frame = parent.clone();
        let mut permission_token = 0i64;

        let _ = frame3.add_PermissionRequested(
            &FramePermissionRequestedEventHandler::create(Box::new(move |_, args| {
                if let Some(args) = args {
                    let mut kind = COREWEBVIEW2_PERMISSION_KIND::default();
                    args.PermissionKind(&mut kind)?;

                    let state = if kind == COREWEBVIEW2_PERMISSION_KIND_NOTIFICATIONS {
                        if ask_notification_permission(&parent_for_frame) {
                            COREWEBVIEW2_PERMISSION_STATE_ALLOW
                        } else {
                            COREWEBVIEW2_PERMISSION_STATE_DENY
                        }
                    } else if should_allow_permission(kind) {
                        COREWEBVIEW2_PERMISSION_STATE_ALLOW
                    } else {
                        COREWEBVIEW2_PERMISSION_STATE_DEFAULT
                    };
                    if kind != COREWEBVIEW2_PERMISSION_KIND_UNKNOWN_PERMISSION {
                        args.SetState(state)?;
                        args.SetHandled(true)?;
                    }
                }
                Ok(())
            })),
            &mut permission_token,
        );

        let frame_for_injection = frame3.clone();
        let mut content_token = 0i64;

        let _ = frame3.add_ContentLoading(
            &FrameContentLoadingEventHandler::create(Box::new(move |_, _| {
                // 通知桥、剪贴板图片桥、帧内日志桥与 boot 探测桥需要 iframe 上下文执行。
                // （导航桥 / 缩放快捷键 / 全局样式已分别由 dsh-tauri、dsh-tauri-ui 插件承担。）
                for script in [
                    crate::desktop::notification::NOTIFICATION_SHIM_JS,
                    crate::desktop::paste::PASTE_SHIM_JS,
                    crate::desktop::frame_log::FRAME_LOG_BRIDGE_JS,
                    crate::desktop::plugin_boot::PLUGIN_BOOT_RELOAD_JS,
                ] {
                    let script = HSTRING::from(script);
                    let _ = frame_for_injection.ExecuteScript(
                        &script,
                        &ExecuteScriptCompletedHandler::create(Box::new(|_, _| Ok(()))),
                    );
                }
                Ok(())
            })),
            &mut content_token,
        );
    }

    let origins = notification_origins(&parent);
    let mut token = 0i64;

    unsafe {
        let controller = webview.controller();
        let webview2 = controller.CoreWebView2()?;

        if let Err(e) = reset_persisted_notification_permissions(&webview2, &origins) {
            log::warn!("[notification] failed to reset permissions: {e}");
        }

        // 1. 处理顶级页面权限请求
        let parent_for_top = parent.clone();
        webview2.add_PermissionRequested(
            &PermissionRequestedEventHandler::create(Box::new(move |_, args| {
                if let Some(args) = args {
                    let mut kind = COREWEBVIEW2_PERMISSION_KIND::default();
                    args.PermissionKind(&mut kind)?;

                    let state = if kind == COREWEBVIEW2_PERMISSION_KIND_NOTIFICATIONS {
                        if ask_notification_permission(&parent_for_top) {
                            COREWEBVIEW2_PERMISSION_STATE_ALLOW
                        } else {
                            COREWEBVIEW2_PERMISSION_STATE_DENY
                        }
                    } else if should_allow_permission(kind) {
                        COREWEBVIEW2_PERMISSION_STATE_ALLOW
                    } else {
                        COREWEBVIEW2_PERMISSION_STATE_DEFAULT
                    };
                    if kind != COREWEBVIEW2_PERMISSION_KIND_UNKNOWN_PERMISSION {
                        args.SetState(state)?;
                    }
                }
                Ok(())
            })),
            &mut token,
        )?;

        // 2. 处理 iframe 页面权限与 JS 脚本注入
        if let Ok(webview4) = webview2.cast::<ICoreWebView2_4>() {
            let mut frame_created_token = 0i64;
            let parent_for_frame_created = parent.clone();

            webview4.add_FrameCreated(
                &FrameCreatedEventHandler::create(Box::new(move |_, args| {
                    if let Some(args) = args {
                        if let Ok(frame) = args.Frame() {
                            if let Ok(frame3) = frame.cast::<ICoreWebView2Frame3>() {
                                setup_frame_handlers(frame3, parent_for_frame_created.clone());
                            }
                        }
                    }
                    Ok(())
                })),
                &mut frame_created_token,
            )?;
        }
    }

    Ok(())
}

//! 桌宠外置窗口：独立的透明、置顶、无边框小窗口，用于展示 dsh 会话状态的
//! 动画宠物（桌宠外置化，issue #308）。
//!
//! 设计要点（参考 BongoCat 的多 WebView 桌宠方案）：
//! - 独立窗口 label `pet`，`WebviewUrl::App("pet.html")`，与主窗口（`main`）
//!   并行，由主 webview 监听 dsh-container 的 invoke 桥来操控；
//! - 窗口特性：`transparent + always_on_top + decorations(false) +
//!   skip_taskbar + shadow(false) + accept_first_mouse`，打造覆盖在普通
//!   窗口之上的不抢占焦点的宠物层；
//! - 几何（位置/大小）持久化到独立 store 键 `pet_window_state`，重启恢复，
//!   不与主窗口几何互相污染（主窗口用 `config::window_state`）。
//!
//! 平台说明：
//! - macOS 透明窗口需要 `macOSPrivateApi`（见 tauri.conf.json `app` 段），且
//!   Tauri 的 masking 需 `macos-private-api` Cargo feature，由
//!   `src-tauri/Cargo.toml` 按平台门控开启。这里透明依赖平台原生支持，创建失败
//!   时回退为非透明窗口继续工作。
//! - `always_on_top` 在 Windows 上 Tauri 原生 API 即可保持置顶（BongoCat 为
//!   额外稳定性用 SetWindowPos 循环轮询，本项目暂不做该平台特定加固）。
//! - 原生 Wayland 会话下 `always_on_top` 与 `set_position` 都不生效，桌宠被主窗口
//!   遮挡（issue #649，上游 tauri-apps/tao#1134 已按「Wayland 不支持」补文档结案）。
//!   同一后端下 `outer_position()` 恒为 `{x:0,y:0}`，几何持久化因此一并跳过。
//!   判定见 `crate::pet_overlay_supported`，前端据此提示用户。

use crate::config::{store_dat_file_name, STORE_PET_WINDOW_STATE_KEY};
use serde::{Deserialize, Serialize};
use tauri::{
    AppHandle, Manager, PhysicalPosition, Runtime, WebviewUrl, WebviewWindow, WebviewWindowBuilder,
    Window,
};
use tauri_plugin_store::StoreExt;

/// 桌宠窗口的 label（Tauri 窗口标识，脚本层与能力配置以此引用）。
pub const PET_WINDOW_LABEL: &str = "pet";
/// 内置视频基准尺寸（dsh-pet 呆味预览帧 220x124，透明画布）。
pub const PET_SPRITE_BASE_WIDTH: f64 = 220.0;
/// 窗口留白（逻辑像素）：顶部为 Toast 绘制区，但由 pet WebView 根据
/// 实际 DOM 命中区域动态调用 setIgnoreCursorEvents 控制透明区域穿透。
const PET_WINDOW_PAD_X: f64 = 32.0;
const PET_WINDOW_TOP_PAD: f64 = 72.0;
const PET_WINDOW_BOTTOM_PAD: f64 = 10.0;
/// 顶栏 Toast 区的最小窗口宽度（逻辑像素）：桌宠较小时仍保证气泡可读，
/// 与 pet WebView 的 PET_BUBBLE_MIN_WIDTH 保持一致。
const PET_WINDOW_MIN_WIDTH: f64 = 420.0;
/// 预设宠物默认画布 16:9（高/宽 = 9/16）：与 dsh-pet 协议画布一致
/// （WebM 与 macOS 的 HEVC-with-Alpha MOV 共用同一画布）。
const PET_BUILTIN_ASPECT: f64 = 9.0 / 16.0;
/// Codex 图集（自定义精灵图，或清单条目声明 `kind: "codex"`）的 8x11 / 192x208 比例；
/// 实际比例以前端加载后为准，这里仅作为窗口初始/DPI 尺寸的近似，避免与前端互相打架。
const PET_CUSTOM_ASPECT: f64 = 208.0 / 192.0;
/// 宠物大小百分比合法区间（设置页滑条 50%–200%；bridge/pet.rs 引用同一常量）。
pub const PET_SIZE_MIN_PERCENT: f64 = 50.0;
pub const PET_SIZE_MAX_PERCENT: f64 = 200.0;
/// 未设置 pet_size 时的默认缩放（100% = 精灵图原始尺寸）。
pub const PET_SIZE_DEFAULT_PERCENT: f64 = 100.0;

/// 持久化的桌宠窗口位置（仅记录位置；大小由设置页 pet_size 百分比实时推导）。
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct PetWindowPosition {
    /// 非 None 时恢复物理位置；None 表示用户从未拖动过，走系统默认（居中靠下）。
    pub x: Option<i32>,
    pub y: Option<i32>,
}

/// 读取上次保存的桌宠窗口位置；无记录时返回默认（None，位置未定）。
pub fn get_pet_window_position<R: Runtime>(app: &AppHandle<R>) -> PetWindowPosition {
    let store = app
        .store(store_dat_file_name())
        .expect("Failed to load store for pet window position");
    let raw = store.get(STORE_PET_WINDOW_STATE_KEY);
    raw.as_ref()
        .and_then(|value| {
            serde_json::from_value(crate::config::unwrap_json_value(value).into_owned()).ok()
        })
        .unwrap_or_default()
}

/// 保存桌宠窗口位置（用户拖动后由 Moved 事件调用）。
///
/// 原生 Wayland 下跳过写入：两个调用点的位置都取自 `outer_position()`，而 GDK 的
/// Wayland 后端不向客户端报告窗口在屏幕上的坐标，该调用返回 `{x:0,y:0}` 且不报错。
/// 照写会把上一次在 X11 会话里存下的有效位置覆盖成原点（issue #649）。
pub fn save_pet_window_position<R: Runtime>(app: &AppHandle<R>, position: &PetWindowPosition) {
    if !crate::pet_overlay_supported_env() {
        return;
    }
    let store = app
        .store(store_dat_file_name())
        .expect("Failed to load store for pet window position");
    let serialized =
        serde_json::to_value(position).expect("Failed to serialize pet window position");
    store.set(STORE_PET_WINDOW_STATE_KEY, serialized);
    store.save().expect("Failed to save pet window position");
}

/// 采样当前桌宠窗口位置并保存（窗口 Moved 时由 builder 调用）。
///
/// 接收基础 `Window`（`on_window_event` 回调类型），仅需其外部位与可见性。
pub fn save_pet_window_geometry<R: Runtime>(window: &Window<R>) {
    // 窗口未显示或正在全屏时采样到的可能是瞬态/无意义的位置，跳过。
    if !window.is_visible().unwrap_or(false) {
        return;
    }
    let Some(pos) = window.outer_position().ok() else {
        return;
    };
    let app = window.app_handle().clone();
    save_pet_window_position(
        &app,
        &PetWindowPosition {
            x: Some(pos.x),
            y: Some(pos.y),
        },
    );
}

/// 读取宠物大小百分比（设置持久化值；缺省回落默认，越界收敛进合法区间）。
pub fn get_pet_size_percent<R: Runtime>(app: &AppHandle<R>) -> f64 {
    crate::config::get_store_dat_setting(app)
        .pet_size
        .unwrap_or(PET_SIZE_DEFAULT_PERCENT)
        .clamp(PET_SIZE_MIN_PERCENT, PET_SIZE_MAX_PERCENT)
}

/// 当前激活宠物使用的画布比例（高度/宽度）：预设宠物（未限定 id）默认 dsh-pet 的
/// 16:9 透明视频画布，自定义精灵图（chat:/codex: 来源限定 id）用 208/192。
/// 真正的比例由 pet WebView 拿到清单条目/图集后实时修正，这里只是窗口创建与
/// DPI 变化时的初始近似。
pub fn pet_window_aspect<R: Runtime>(app: &AppHandle<R>) -> f64 {
    let setting = crate::config::get_store_dat_setting(app);
    let active = setting
        .active_pet
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    // 来源限定 id（chat:/codex:）是自定义精灵图；未限定 id（预设宠物）用 WebM 9/16。
    if active.map(|value| !value.contains(':')).unwrap_or(true) {
        PET_BUILTIN_ASPECT
    } else {
        PET_CUSTOM_ASPECT
    }
}

/// 由百分比换算桌宠窗口逻辑尺寸：按当前宠物画布比例缩放，气泡与阴影留白保持可读固定高度。
pub fn pet_window_logical_size(percent: f64, aspect: f64) -> (f64, f64) {
    let scale = percent / 100.0;
    (
        ((PET_SPRITE_BASE_WIDTH * scale) + PET_WINDOW_PAD_X).max(PET_WINDOW_MIN_WIDTH),
        (PET_SPRITE_BASE_WIDTH * aspect * scale) + PET_WINDOW_TOP_PAD + PET_WINDOW_BOTTOM_PAD,
    )
}

/// 实时应用宠物大小：窗口已存在时直接重设尺寸（设置页拖动条拖动中实时调用）。
pub fn apply_pet_size<R: Runtime>(app: &AppHandle<R>) {
    let Some(window) = app.get_webview_window(PET_WINDOW_LABEL) else {
        return;
    };
    let (width, height) =
        pet_window_logical_size(get_pet_size_percent(app), pet_window_aspect(app));
    if window
        .set_size(tauri::LogicalSize::new(width, height))
        .is_ok()
    {
        // 放大后重新夹紧当前位置，避免窗口右侧或底部被推出当前显示器。
        let _ = move_pet_window(app, 0, 0);
    }
}

/// 将窗口左上角限制到单个显示器内；窗口大于显示器时贴齐其左上角。
#[allow(clippy::too_many_arguments)]
fn clamp_window_position(
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    monitor_x: i32,
    monitor_y: i32,
    monitor_width: u32,
    monitor_height: u32,
) -> (i32, i32) {
    let left = i64::from(monitor_x);
    let top = i64::from(monitor_y);
    let right = left + i64::from(monitor_width);
    let bottom = top + i64::from(monitor_height);
    let max_x = (right - i64::from(width)).max(left);
    let max_y = (bottom - i64::from(height)).max(top);
    (
        i64::from(x).clamp(left, max_x) as i32,
        i64::from(y).clamp(top, max_y) as i32,
    )
}

/// 按物理像素增量移动桌宠，收敛到最近可见显示器并持久化最终位置。
pub fn move_pet_window<R: Runtime>(
    app: &AppHandle<R>,
    delta_x: i32,
    delta_y: i32,
) -> Result<(), String> {
    let window = app
        .get_webview_window(PET_WINDOW_LABEL)
        .ok_or_else(|| "PET_WINDOW_NOT_FOUND: pet window has not been created".to_string())?;
    let current = window.outer_position().map_err(|error| {
        format!("PET_WINDOW_POSITION_FAILED: failed to read pet window position: {error}")
    })?;
    let size = window.outer_size().map_err(|error| {
        format!("PET_WINDOW_SIZE_FAILED: failed to read pet window size: {error}")
    })?;
    let desired_x = current.x.saturating_add(delta_x);
    let desired_y = current.y.saturating_add(delta_y);
    let center_x = i64::from(desired_x) + i64::from(size.width) / 2;
    let center_y = i64::from(desired_y) + i64::from(size.height) / 2;
    let monitors = app.available_monitors().map_err(|error| {
        format!("PET_MONITOR_LIST_FAILED: failed to list visible monitors: {error}")
    })?;
    if monitors.is_empty() {
        return Err("PET_MONITOR_NOT_FOUND: no visible monitor is available".to_string());
    }

    // 目标中心已进入某屏时直接选择该屏；跨过屏幕间隙时选距离目标最近的屏幕。
    let monitor = monitors
        .iter()
        .find(|monitor| {
            let pos = monitor.position();
            let area = monitor.size();
            let right = i64::from(pos.x) + i64::from(area.width);
            let bottom = i64::from(pos.y) + i64::from(area.height);
            center_x >= i64::from(pos.x)
                && center_x < right
                && center_y >= i64::from(pos.y)
                && center_y < bottom
        })
        .or_else(|| {
            monitors.iter().min_by_key(|monitor| {
                let pos = monitor.position();
                let area = monitor.size();
                let left = i64::from(pos.x);
                let top = i64::from(pos.y);
                let right = left + i64::from(area.width);
                let bottom = top + i64::from(area.height);
                let dx = if center_x < left {
                    left - center_x
                } else if center_x >= right {
                    center_x - right + 1
                } else {
                    0
                };
                let dy = if center_y < top {
                    top - center_y
                } else if center_y >= bottom {
                    center_y - bottom + 1
                } else {
                    0
                };
                dx.saturating_mul(dx).saturating_add(dy.saturating_mul(dy))
            })
        })
        .expect("非空显示器列表应能选择目标显示器");
    let monitor_pos = monitor.position();
    let monitor_size = monitor.size();
    let (x, y) = clamp_window_position(
        desired_x,
        desired_y,
        size.width,
        size.height,
        monitor_pos.x,
        monitor_pos.y,
        monitor_size.width,
        monitor_size.height,
    );
    window
        .set_position(tauri::Position::Physical(PhysicalPosition::new(x, y)))
        .map_err(|error| format!("PET_WINDOW_MOVE_FAILED: failed to move pet window: {error}"))?;
    save_pet_window_position(
        app,
        &PetWindowPosition {
            x: Some(x),
            y: Some(y),
        },
    );
    Ok(())
}

/// 确保桌宠窗口存在并恢复位置。
///
/// 幂等：已注册时直接复用返回；不存在（首次启用，或上次收起时已被销毁）时
/// 创建 `pet` 窗口并恢复上一次保存的位置（无记录则默认定位在主屏右下角略偏上，
/// 避免遮挡主工作区）。
///
/// 创建窗口只能来自 app setup 或异步运行时的命令任务：`WebviewWindowBuilder::build()`
/// 经 channel 等主线程事件循环回包，主线程调用会死锁；销毁窗口则**绝不能**在主线程
/// 调用（`WindowMessage::Destroy` 在主线程直接 panic）。两条约束都由
/// `bridge::pet::defer_pet_window_op` 统一保证。
pub fn ensure_pet_window<R: Runtime>(app: &AppHandle<R>) -> tauri::Result<WebviewWindow<R>> {
    if let Some(window) = app.get_webview_window(PET_WINDOW_LABEL) {
        return Ok(window);
    }
    if !crate::pet_overlay_supported_env() {
        log::warn!(
            "PET_OVERLAY_UNSUPPORTED: always-on-top and absolute positioning are unavailable on \
             a native Wayland session; the pet window is covered by other windows and does not \
             stay where it was placed. Enable the XWayland option in pet settings to restore them."
        );
    }
    let app_handle = app.clone();
    let (width, height) =
        pet_window_logical_size(get_pet_size_percent(app), pet_window_aspect(app));
    // 非 Windows 平台在此前加入注入脚本时再赋值，故需要 mut；Windows 下保持只读。
    #[allow(unused_mut)]
    let mut builder =
        WebviewWindowBuilder::new(app, PET_WINDOW_LABEL, WebviewUrl::App("pet.html".into())).data_directory(crate::managed::path("data/electron-user-data/webview"))
            .title("Deepseek Harness Pet")
            .inner_size(width, height)
            .resizable(false)
            .maximizable(false)
            .transparent(true)
            .always_on_top(true)
            .decorations(false)
            .skip_taskbar(true)
            .shadow(false)
            .accept_first_mouse(true)
            .visible(false);

    // 非 Windows 平台经 initialization script 让 dsh 容器的桥/兼容注入生效，
    // 与主窗口保持一致（桌宠页同样可能加载共享的前端模块）。
    #[cfg(not(windows))]
    {
        builder = builder
            .initialization_script_for_all_frames(crate::desktop::compat::ABORT_SIGNAL_ANY_SHIM_JS)
            .initialization_script_for_all_frames(crate::desktop::compat::ITERATOR_HELPERS_SHIM_JS)
            .initialization_script_for_all_frames(
                crate::desktop::notification::NOTIFICATION_SHIM_JS,
            )
            .initialization_script_for_all_frames(crate::desktop::paste::PASTE_SHIM_JS)
            .initialization_script_for_all_frames(
                crate::desktop::plugin_boot::PLUGIN_BOOT_RELOAD_JS,
            );
    }

    let window = builder.build()?;
    let app_for_pos = app_handle.clone();
    let saved = get_pet_window_position(&app_for_pos);
    if let (Some(x), Some(y)) = (saved.x, saved.y) {
        // 恢复的位置必须落在某个可见屏幕内，否则回退默认定位（防止显示器
        // 拓扑变化后窗口被放到屏幕外不可见）。
        if position_on_any_monitor(&window, x, y) {
            let _ = window.set_position(tauri::Position::Physical(PhysicalPosition::new(x, y)));
        } else {
            place_pet_at_default(&window);
        }
    } else {
        place_pet_at_default(&window);
    }
    Ok(window)
}

/// 判断给定物理坐标（窗口左上角）是否落在任一可见屏幕内（含边缘相交）。
///
/// 显示器拓扑可能在保存位置后变化（拔掉外接屏 / 改变排布），恢复到一个不
/// 属于任何屏幕的位置会让桌宠「消失」在屏幕外；这里只在原位置仍有效时恢复。
fn position_on_any_monitor<R: Runtime>(window: &WebviewWindow<R>, x: i32, y: i32) -> bool {
    let app = window.app_handle();
    let Ok(monitors) = app.available_monitors() else {
        return false;
    };
    // 以当前设置的窗口逻辑尺寸 × 缩放系数近似命中矩形，允许窗口底部/右侧
    // 探出一点点也不误判。
    let (lw, lh) = pet_window_logical_size(
        get_pet_size_percent(window.app_handle()),
        pet_window_aspect(window.app_handle()),
    );
    let w = (lw * window.scale_factor().unwrap_or(1.0)) as i32;
    let h = (lh * window.scale_factor().unwrap_or(1.0)) as i32;
    let hit_left = x;
    let hit_top = y;
    let hit_right = x + w;
    let hit_bottom = y + h;
    monitors.iter().any(|m| {
        let pos = m.position();
        let size = m.size();
        let (ml, mt) = (pos.x, pos.y);
        let (mr, mb) = (pos.x + size.width as i32, pos.y + size.height as i32);
        // 两个矩形至少有一个点的交集：窗口左上角在屏内，或屏被窗口覆盖。
        hit_left < mr && hit_right > ml && hit_top < mb && hit_bottom > mt
    })
}

/// 把桌宠窗口放到主工作区右下角略偏上（主屏内、避开底部任务栏高度）。
fn place_pet_at_default<R: Runtime>(window: &WebviewWindow<R>) {
    let app = window.app_handle();
    let Some(monitor) = app.primary_monitor().ok().flatten() else {
        return;
    };
    let mon_pos = monitor.position();
    let mon_size = monitor.size();
    // 距屏幕右下角 32px 的物理偏移；尺寸 = 当前设置逻辑尺寸 × 屏幕缩放系数。
    let (lw, lh) = pet_window_logical_size(get_pet_size_percent(app), pet_window_aspect(app));
    let w = (lw * monitor.scale_factor()) as i32;
    let h = (lh * monitor.scale_factor()) as i32;
    let x = mon_pos.x + mon_size.width as i32 - w - 32;
    let y = mon_pos.y + mon_size.height as i32 - h - 96;
    let _ = window.set_position(tauri::Position::Physical(PhysicalPosition::new(x, y)));
}

/// 显示或关闭桌宠窗口。
///
/// # 隐藏 = 销毁窗口实例（issue #469）
///
/// 这里**不做 hide**：隐藏只是把窗口从屏幕上撤下，WebView 进程与页面都还在，桌宠的
/// 双 `<video>` 会继续解码播放——Chromium/WebView2 对「播放中（未暂停）的 video」
/// 无条件持有 Video Wake Lock，屏幕因此永远无法息屏，还白占 CPU（用户报告：收起宠物
/// 后仍无法黑屏）。销毁窗口才是真正「收起」：webview 进程随窗口一起消失，视频暂停、
/// 唤醒锁释放、CPU 归零。代价是重新显示要重建 webview（页面前端挂载时用
/// `get_pet_status` 拉取状态，不依赖创建时的事件投递）。
///
/// # 线程约束（务必读完再改）
///
/// `tauri-runtime-wry` 对主线程上的窗口生命周期消息是「创建会死锁、销毁会 panic」：
///
/// - **销毁**走 `WindowMessage::Destroy`，主线程调用直接
///   `panic!("cannot handle \`WindowMessage::Destroy\` on the main thread")`
///   （tauri-runtime-wry 2.11.4 lib.rs:3494）。command handler 在主线程执行，所以
///   收起命令必须经 `bridge::pet::defer_pet_window_op` 丢到异步运行时再调本函数。
/// - **创建**（`ensure_pet_window` → `WebviewWindowBuilder::build()`）经 channel 等
///   主线程事件循环回包，仅允许 app setup 或异步运行时任务调用（app setup 在事件
///   循环初始化前、不与回包竞争，是唯一的主线程例外）。
pub fn set_pet_window_visible<R: Runtime>(app: &AppHandle<R>, visible: bool) -> Result<(), String> {
    if !visible {
        if let Some(window) = app.get_webview_window(PET_WINDOW_LABEL) {
            window
                .destroy()
                .map_err(|error| format!("PET_WINDOW_DESTROY_FAILED: {error}"))?;
        }
        return Ok(());
    }
    let window =
        ensure_pet_window(app).map_err(|error| format!("PET_WINDOW_CREATE_FAILED: {error}"))?;
    window
        .show()
        .map_err(|error| format!("PET_WINDOW_SHOW_FAILED: {error}"))?;
    Ok(())
}

/// setup 阶段按「是否永久启用」决定桌宠窗口的初始状态。
///
/// 启用才创建并显示；未启用**不创建**：窗口是「显示宠物」的唯一目的，没人看时连
/// webview 都不该存在（隐藏窗口同样会加载 pet.html、播放动画）。窗口此后由
/// [`set_pet_window_visible`] 按需创建/销毁。
pub fn init_pet_window<R: Runtime>(app: &AppHandle<R>) {
    if !crate::config::get_store_dat_setting(app).pet_enabled {
        // 全新安装默认不启用桌宠：不预创建窗口（也顺带不触发 Linux 未 realize
        // 窗口的穿透请求路径）。
        return;
    }
    if let Err(error) = set_pet_window_visible(app, true) {
        log::error!("PET_WINDOW_INIT_FAILED: failed to create pet window: {error}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pet_window_position_serde_roundtrip() {
        let pos = PetWindowPosition {
            x: Some(120),
            y: Some(240),
        };
        let json = serde_json::to_string(&pos).expect("serialize");
        let parsed: PetWindowPosition = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(parsed.x, Some(120));
        assert_eq!(parsed.y, Some(240));
    }

    #[test]
    fn pet_window_position_defaults_to_none() {
        // 缺失字段 / 空对象时应回落默认（未定制位置），不能反序列化失败
        let parsed: PetWindowPosition = serde_json::from_str("{}").expect("deserialize");
        assert!(parsed.x.is_none());
        assert!(parsed.y.is_none());

        let default = PetWindowPosition::default();
        assert!(default.x.is_none() && default.y.is_none());
    }

    #[test]
    fn pet_window_logical_size_scales_with_percent() {
        // 窗口顶部为 Toast 区，宠物资源本身仍按内置 16:9 画布或 8x11 atlas 尺寸绘制。
        for percent in [50.0, 100.0, 200.0] {
            let (width, height) = pet_window_logical_size(percent, PET_CUSTOM_ASPECT);
            let scale = percent / 100.0;
            // 大比例时窗口跟随宠物宽度，小比例时兜底到 Toast 区最小宽度。
            assert_eq!(
                width,
                (PET_SPRITE_BASE_WIDTH * scale + PET_WINDOW_PAD_X).max(PET_WINDOW_MIN_WIDTH)
            );
            assert_eq!(
                height,
                PET_SPRITE_BASE_WIDTH * PET_CUSTOM_ASPECT * scale + 82.0
            );
        }
        // 内置鲸鱼为 16:9 画布，窗口高度远小于 8x11 图集，避免窗口过高产生大片透明区。
        let (_, builtin_height) = pet_window_logical_size(100.0, PET_BUILTIN_ASPECT);
        assert_eq!(
            builtin_height,
            PET_SPRITE_BASE_WIDTH * PET_BUILTIN_ASPECT + 82.0
        );
    }

    #[test]
    fn pet_window_aspect_matches_builtin_and_custom() {
        // 未设置 / 空白 / 未限定 id（预设 WebM）都走内置 16:9 比例；
        // 来源限定 id（chat:/codex:）走自定义图集比例。
        // 使用一个真实 AppHandle 才能读设置，这里仅验证比例常量与归一化分支的纯逻辑。
        assert_eq!(PET_BUILTIN_ASPECT, 9.0 / 16.0);
        assert_eq!(PET_CUSTOM_ASPECT, 208.0 / 192.0);
        let is_builtin = |active: Option<&str>| {
            active
                .map(str::trim)
                .filter(|v| !v.is_empty())
                .map(|v| !v.contains(':'))
                .unwrap_or(true)
        };
        assert!(is_builtin(None));
        assert!(is_builtin(Some("   ")));
        assert!(is_builtin(Some("maid-deepseek-whale")));
        assert!(is_builtin(Some("another-preset")));
        assert!(!is_builtin(Some("codex:blue_whale")));
        assert!(!is_builtin(Some("chat:cat")));
    }

    #[test]
    fn pet_window_width_crosses_bubble_minimum_at_large_sizes() {
        assert_eq!(
            pet_window_logical_size(50.0, PET_BUILTIN_ASPECT),
            (420.0, 143.875)
        );
        assert_eq!(
            pet_window_logical_size(100.0, PET_BUILTIN_ASPECT),
            (420.0, 205.75)
        );
        assert_eq!(
            pet_window_logical_size(200.0, PET_BUILTIN_ASPECT),
            (472.0, 329.5)
        );
    }

    #[test]
    fn clamp_window_position_handles_extreme_coordinates_and_sizes() {
        assert_eq!(
            clamp_window_position(i32::MAX, i32::MIN, 20, 10, -1920, -1080, 1920, 1080),
            (-20, -1080)
        );
        assert_eq!(
            clamp_window_position(0, 0, u32::MAX, u32::MAX, i32::MIN, i32::MIN, 0, 0),
            (i32::MIN, i32::MIN)
        );
    }

    #[test]
    fn clamp_window_position_keeps_entire_pet_on_monitor() {
        assert_eq!(
            clamp_window_position(1900, 1000, 252, 244, 0, 0, 1920, 1080),
            (1668, 836)
        );
        assert_eq!(
            clamp_window_position(-2000, -500, 252, 244, -1920, 0, 1920, 1080),
            (-1920, 0)
        );
        assert_eq!(
            clamp_window_position(100, 100, 900, 700, 0, 0, 800, 600),
            (0, 0),
            "窗口大于显示器时应贴齐显示器左上角"
        );
    }
}

