//! browser-auth 载体补丁：让管理实例的本地桌面载体无需启动 token 即可访问内置 Web。
//!
//! 背景：dsh 核心自带启动鉴权以来，`dsh --profile web` 把 SPA 门禁在「每进程随机
//! 启动 token」之后——`GET /` 无有效 token / cookie 一律 401
//! （`@deepseek-ai/dsh-client-connection` 的 `BrowserAuth`）。社区桌面的设计是
//! 「alpha 鉴权由启动前的桌面端 patch 处理，iframe 永远不携带启动 token」
//! （见 `src/store/modules/harness/utils.ts`）：内嵌 iframe 用的是干净的
//! `http://127.0.0.1:<port>?t=…&dshDesktop=1`，从不带上 token；同时
//! `is_dsh_running` 的就绪探测也是无 token 的 `GET /`（要求 200）。
//!
//! 上游随桌面端发行的核心版本比本补丁集新，连接层新增了上述启动 token，而桌面端
//! 补丁集尚未覆盖它，于是：`GET /` 恒为 401 → 就绪探测永不通过 → 状态到不了
//! Running（也就不会落就绪文件），且内嵌 GUI 会显示鉴权提示。本补丁补齐上游缺失
//! 的「桌面端鉴权补丁」：把 `BrowserAuth.isAuthenticated` 判定改成恒真，等价于
//! 「本地载体已被信任」。
//!
//! 信任边界：Harness 只绑定 `127.0.0.1`，且 `/api` 另有 Origin/Referer 浏览器信任
//! 围栏（`--trusted-host`）拦截跨站请求；本补丁只取消「每进程启动 token」这一层，
//! 面向的是本机单用户隔离实例（自有端口、自有核心副本、自有 Electron user-data），
//! 与随包上游桌面端对其内嵌载体的既定处置一致。
//!
//! 目标选择：**活动核心**（本地核心或预打包核心），读写与幂等判定统一交给
//! [`crate::utils::patch_dsh`]；本模块只提供纯函数式补丁判定 [`patch_source`]。
//!
//! 幂等与容错：目标已含标记即跳过；文件缺失或锚点因上游布局变更找不到 → 跳过并
//! 告警，不阻断启动。挂点：`service::workflow::launch` 启动 dsh 进程前，与其余
//! 核心补丁同一位置（最佳努力，失败只告警）。

use std::path::Path;

use crate::utils::{patch_core_file, patch_dsh, PatchOutcome};

/// 幂等标记：注入语句里带注释，重跑时直接命中「已打过」。
const MARKER: &str = "WhaleRealm managed carrier: trust local desktop requests";

/// `BrowserAuth.isAuthenticated` 方法定义锚点（带方法名与形参，避免命中调用点）。
const ANCHOR: &str = "isAuthenticated(request) {";

/// 相对活动核心安装目录的 dsh-client-connection 包内路径。
const CONNECTION_INDEX_JS: &str =
    "node_modules/@deepseek-ai/dsh-client-connection/lib/index.js";

/// 幂等补丁逻辑的纯函数部分（便于单测，不触碰文件系统）。
///
/// 在 `isAuthenticated(request) {` 之后插入 `return true;`，按锚点所在行的**实际
/// 前导缩进**再进一级，避免上游产物缩进（tab/空格）变化时插出坏行。
fn patch_source(source: &str) -> PatchOutcome {
    if source.contains(MARKER) {
        return PatchOutcome::AlreadyPatched;
    }
    let Some(position) = source.find(ANCHOR) else {
        return PatchOutcome::AnchorMissing;
    };
    let after = position + ANCHOR.len();
    let line_start = source[..position]
        .rfind('\n')
        .map(|index| index + 1)
        .unwrap_or(0);
    let indent: String = source[line_start..position]
        .chars()
        .take_while(|character| *character == '\t' || *character == ' ')
        .collect();
    let body_indent = format!("{indent}\t");
    let mut patched = source.to_string();
    patched.insert_str(
        after,
        &format!("\n{body_indent}/* {MARKER} */\n{body_indent}return true;"),
    );
    PatchOutcome::Patched(patched)
}

/// 对活动核心的 dsh-client-connection `lib/index.js` 应用补丁（幂等）。
/// 返回 Err 表示读/写失败；文件缺失、已打过、锚点变更均静默跳过（Ok）。
pub fn apply(app_handle: &tauri::AppHandle) -> Result<(), String> {
    patch_dsh(app_handle, CONNECTION_INDEX_JS, patch_source)
}

/// 对显式给定的核心安装目录施加本补丁（E2E 编排复用，无需运行中的桌面端）。
pub fn apply_at(core_dir: &Path) -> Result<(), String> {
    patch_core_file(core_dir, CONNECTION_INDEX_JS, patch_source)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// 上游打包产物里该类方法的最小上下文（单 tab 缩进）。
    const SOURCE: &str = "\t/** verify */\n\tisAuthenticated(request) {\n\t\tconst authority = requestAuthority(request.headers);\n\t\treturn true;\n\t}\n";

    #[test]
    fn inserts_return_true_after_anchor() {
        match patch_source(SOURCE) {
            PatchOutcome::Patched(patched) => {
                assert!(patched.contains(MARKER));
                assert!(patched.contains(
                    "isAuthenticated(request) {\n\t\t/* WhaleRealm managed carrier: trust local desktop requests */\n\t\treturn true;\n\t\tconst authority"
                ));
            }
            other => panic!("expected Patched, got {other:?}"),
        }
    }

    #[test]
    fn matches_double_tab_indentation() {
        let double_tab = "\t\tisAuthenticated(request) {\n\t\t\tconst authority = 0;\n";
        match patch_source(double_tab) {
            PatchOutcome::Patched(patched) => {
                // 插入体与锚点行对齐后再进一级（双 tab → 三 tab）
                assert!(patched.contains(
                    "isAuthenticated(request) {\n\t\t\t/* WhaleRealm managed carrier: trust local desktop requests */\n\t\t\treturn true;"
                ));
                assert!(!patched.contains("\n\t\treturn true;"));
            }
            other => panic!("expected Patched, got {other:?}"),
        }
    }

    #[test]
    fn is_idempotent() {
        let PatchOutcome::Patched(patched) = patch_source(SOURCE) else {
            panic!("expected Patched");
        };
        assert_eq!(patch_source(&patched), PatchOutcome::AlreadyPatched);
    }

    #[test]
    fn skips_when_anchor_missing() {
        let altered = "isAuthenticated(request, extra) {\n\treturn false;\n}\n";
        assert_eq!(patch_source(altered), PatchOutcome::AnchorMissing);
    }
}

//! 安装包下载、完整性校验与交付系统处理器打开。
//!
//! 下载源策略：先取 `expanded_assets` 页面的 SHA-256 摘要作为完整性凭据，再选择
//! 下载源——镜像兜底（ghfast.top）仅在已取得可信摘要时才可使用，否则宁可失败，
//! 防止第三方镜像投毒未被察觉；官方 GitHub 直连在摘要缺失时仍可按旧行为下载，
//! 下载后若有摘要则强制校验。

use std::path::PathBuf;
use std::time::Duration;

use futures_util::StreamExt;
use tauri::{AppHandle, Emitter, Manager};
use tauri_plugin_opener::OpenerExt;

use crate::config;
use crate::service::workflow;

use super::meta::{fetch_latest_release, LatestRelease};
use super::version::current_version;
use super::{DOWNLOAD_TIMEOUT_SECS, UPDATES_DIR};

/// 安装包目录（AppData/updates，不存在则创建）
fn updates_dir(app_handle: &AppHandle) -> Result<PathBuf, String> {
    let dir = app_handle
        .path()
        .app_data_dir().map(|_| crate::managed::path("cache/app-data"))
        .map_err(|e| format!("UPDATE_DIR: {e}"))?
        .join(UPDATES_DIR);
    std::fs::create_dir_all(&dir).map_err(|e| format!("UPDATE_DIR: {e}"))?;
    Ok(dir)
}

/// 安装包存放路径（AppData/updates/<asset_name>）
fn installer_path(app_handle: &AppHandle, asset_name: &str) -> Result<PathBuf, String> {
    Ok(updates_dir(app_handle)?.join(asset_name))
}

/// 检查是否有桌面端新版本。
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DesktopUpdateInfo {
    /// 最新可用版本号（无 `v` 前缀）
    pub version: String,
    /// 当前已安装版本号（无 `v` 前缀）
    pub current_version: String,
    pub tag: String,
    pub published_at: String,
    pub url: String,
    pub asset_name: String,
    pub path: String,
    pub downloaded: bool,
}

/// 检查是否有新版本可用（含安装包是否已下载）
pub async fn check(app_handle: &AppHandle) -> Result<Option<DesktopUpdateInfo>, String> {
    if crate::managed::enabled() {return Ok(None);}
    match fetch_latest_release().await? {
        None => Ok(None),
        Some(r) => {
            let path = installer_path(app_handle, &r.asset_name)?;
            let downloaded = path.exists();
            Ok(Some(DesktopUpdateInfo {
                version: r.version,
                current_version: current_version(),
                tag: r.tag,
                published_at: r.published_at,
                url: r.url,
                asset_name: r.asset_name,
                path: path.to_string_lossy().into_owned(),
                downloaded,
            }))
        }
    }
}

/// 下载进度载荷（前端进度条展示）
#[derive(Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DesktopDownloadProgress {
    pub percentage: f64,
    pub downloaded: u64,
    pub total: u64,
    /// 附加提示（如切换下载源），无提示时为 None
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
}

/// 从单个下载源流式下载安装包到临时文件；失败时清理半成品（避免残留
/// 部分字节被误判为「已下载」）。
async fn download_from_source(
    client: &reqwest::Client,
    url: &str,
    tmp: &std::path::Path,
    app_handle: &AppHandle,
) -> Result<(), String> {
    log::info!("Downloading desktop installer from {}", url);
    let res = client
        .get(url)
        .send()
        .await
        .map_err(|e| format!("UPDATE_DOWNLOAD: {e}"))?
        .error_for_status()
        .map_err(|e| format!("UPDATE_DOWNLOAD: {e}"))?;

    let total = res.content_length().unwrap_or(0);
    let mut file = std::fs::File::create(tmp).map_err(|e| format!("UPDATE_FILE: {e}"))?;
    use std::io::Write;
    let mut downloaded: u64 = 0;
    let mut stream = res.bytes_stream();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|e| format!("UPDATE_DOWNLOAD: {e}"))?;
        file.write_all(&chunk)
            .map_err(|e| format!("UPDATE_FILE: {e}"))?;
        downloaded += chunk.len() as u64;
        let pct = if total > 0 {
            (downloaded as f64 / total as f64) * 100.0
        } else {
            0.0
        };
        let _ = app_handle.emit(
            "desktop-update-progress",
            DesktopDownloadProgress {
                percentage: pct,
                downloaded,
                total,
                message: None,
            },
        );
    }
    drop(file);
    Ok(())
}

/// 安装包下载客户端：长超时（安装包可达数百 MB，慢镜像需要更久），
/// 与检查更新用的 5s `http_client()` 区分。
fn download_client() -> Result<reqwest::Client, String> {
    reqwest::Client::builder()
        .user_agent("deepseek-harness-desktop")
        .timeout(Duration::from_secs(DOWNLOAD_TIMEOUT_SECS))
        .connect_timeout(Duration::from_secs(15))
        .build()
        .map_err(|e| format!("UPDATE_CLIENT: {e}"))
}

/// 组装安装包下载源列表：官方 GitHub 直连 + （存在可信摘要时）ghfast.top 镜像。
///
/// 安全策略：第三方镜像没有独立信任根，仅在其内容可被 SHA-256 校验（摘要已取得）
/// 时才提供兜底；否则只允许官方直连，宁可在官方不可用时失败，也不冒投毒风险。
fn download_sources(release: &LatestRelease) -> Vec<String> {
    let mut urls = vec![release.url.clone()];
    if release.digest.is_some() {
        urls.push(config::mirror_download_url(&release.url));
    }
    urls
}

/// 为下载完成的安装包补充可执行权限（Linux AppImage 必需）。
///
/// 下载时 `File::create` 默认生成 `0644`，AppImage 经 `xdg-open` / 直接执行时
/// 需要可执行位，否则表现为「下载成功但无法打开安装包」（issue #79）。这里
/// 在安装包落到最终路径后再补充 `0755`，Linux 上天然生效；macOS 一并设置
/// 无害；Windows 无此概念，忽略。
#[cfg(unix)]
fn ensure_installer_executable(path: &std::path::Path) -> Result<(), String> {
    use std::os::unix::fs::PermissionsExt;
    let mut perms = std::fs::metadata(path)
        .map_err(|e| format!("UPDATE_FILE: {e}"))?
        .permissions();
    perms.set_mode(0o755);
    std::fs::set_permissions(path, perms).map_err(|e| format!("UPDATE_FILE: {e}"))?;
    Ok(())
}

/// 流式校验安装包文件的 SHA-256。
///
/// 安装包可达数百 MB，先 `std::fs::read` 整块读进内存再校验会翻倍占用内存；
/// 这里按块流式喂给 `Sha256`，完成时仅保留 32 字节摘要。摘要格式接受
/// `sha256:<64hex>` 或裸 `<64hex>`（统一转小写比较）。
fn verify_installer_sha256(path: &std::path::Path, expected: &str) -> Result<(), String> {
    use sha2::Digest;
    use std::io::Read;
    let expected = expected
        .strip_prefix("sha256:")
        .unwrap_or(expected)
        .trim()
        .to_ascii_lowercase();
    if expected.len() != 64 || !expected.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err("INTEGRITY_METADATA_INVALID: expected SHA-256 is invalid".to_string());
    }
    let mut file = std::fs::File::open(path).map_err(|e| format!("UPDATE_FILE: {e}"))?;
    let mut hasher = sha2::Sha256::new();
    let mut buf = [0u8; 64 * 1024];
    loop {
        let n = file
            .read(&mut buf)
            .map_err(|e| format!("UPDATE_FILE: {e}"))?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    let actual = format!("{:x}", hasher.finalize());
    if actual != expected {
        return Err(format!(
            "INTEGRITY_CHECK_FAILED: SHA-256 mismatch, expected {expected}, got {actual}"
        ));
    }
    Ok(())
}

/// 下载桌面端安装包；已下载则直接返回。
///
/// 下载期间通过 `desktop-update-progress` 事件推送进度；完成后返回
/// `DesktopUpdateInfo`（path/downloaded 已更新）。
///
/// 下载源策略：先取 `expanded_assets` 页面的 SHA-256 摘要作为完整性凭据，再
/// 选择下载源——**镜像兜底（ghfast.top）仅在已取得可信摘要时才可使用**，否则
/// 宁可失败，防止第三方镜像投毒未被察觉；官方 GitHub 直连在摘要缺失时仍可
/// 按旧行为下载（兼容早期未填摘要的发布），下载后若有摘要则强制校验。
pub async fn download(app_handle: &AppHandle) -> Result<DesktopUpdateInfo, String> {
    if crate::managed::enabled() {return Err("Updates require a certified WhaleRealm deployment".into());}
    let release = fetch_latest_release()
        .await?
        .ok_or_else(|| "UPDATE_NONE".to_string())?;
    let path = installer_path(app_handle, &release.asset_name)?;

    if path.exists() {
        log::info!("Installer already downloaded: {}", path.display());
        // 已落盘的安装包同样登记为「待安装」：覆盖「上一轮下载后 store 标记丢失」
        // （store 被手工清理/旧版本尚无此标记）的场景，保证退出时仍会自动更新。
        super::pending::set(app_handle, Some((path.as_path(), &release.version)));
        return check(app_handle)
            .await?
            .ok_or_else(|| "UPDATE_NONE".to_string());
    }

    let client = download_client()?;

    // 官方直连 → （可选）ghfast.top 镜像兜底。安装包无 SHA-256 元数据，切换源时
    // 丢弃上一源的部分字节从头下载，避免混用两个源的字节流。
    // 安全策略：镜像兜底要求已有可信摘要，否则不提供镜像（宁可失败）。
    let urls = download_sources(&release);
    if urls.len() == 1 {
        log::warn!(
            "No SHA-256 digest available for {}, mirror fallback disabled",
            release.asset_name
        );
    }
    let tmp = path.with_extension("part");
    let mut last_err = String::new();
    for (index, url) in urls.iter().enumerate() {
        if index > 0 {
            // 走镜像仅在存在可信摘要时发生（见上方 urls 组装）
            let host = reqwest::Url::parse(url)
                .ok()
                .and_then(|parsed| parsed.host_str().map(|h| h.to_string()))
                .unwrap_or_else(|| url.clone());
            log::warn!(
                "Primary desktop update source failed, switching to fallback: {}",
                url
            );
            let _ = app_handle.emit(
                "desktop-update-progress",
                DesktopDownloadProgress {
                    percentage: 0.0,
                    downloaded: 0,
                    total: 0,
                    message: Some(format!("主下载源不可用，已切换镜像源重试（{host}）")),
                },
            );
        }
        // 先写临时文件再原子改名，避免下载中断残留半成品被误判为「已下载」
        let _ = std::fs::remove_file(&tmp);
        match download_from_source(&client, url, &tmp, app_handle).await {
            Ok(()) => {
                last_err.clear();
                break;
            }
            Err(e) => last_err = e,
        }
    }
    if !last_err.is_empty() {
        return Err(format!(
            "UPDATE_DOWNLOAD: {last_err}（已尝试 {} 个下载源）",
            urls.len()
        ));
    }

    // 完整性校验：摘要存在（镜像路径必有）则强制校验，校验失败即拒绝，
    // 不保留为可安装文件，也不能被 open_installer 打开。流式校验避免整块读入内存。
    if let Some(digest) = &release.digest {
        if let Err(e) = verify_installer_sha256(&tmp, digest) {
            let _ = std::fs::remove_file(&tmp);
            return Err(format!("UPDATE_DOWNLOAD: {e}"));
        }
        log::info!("Installer SHA-256 verified for {}", release.asset_name);
    }

    std::fs::rename(&tmp, &path).map_err(|e| format!("UPDATE_FILE: {e}"))?;

    // Linux 下为安装包补充可执行位（AppImage 需要），否则会「下载成功但无法打开」
    #[cfg(unix)]
    ensure_installer_executable(&path)?;

    // 登记「待安装」：用户若没在对话框里立刻安装，关闭桌面端时会自动打开安装器
    // （见 pending::launch_pending_installer）；真正打开安装包后清除该标记。
    super::pending::set(app_handle, Some((path.as_path(), &release.version)));

    check(app_handle)
        .await?
        .ok_or_else(|| "UPDATE_NONE".to_string())
}

/// 校验已规范化的安装包路径确实位于 updates 目录内（防 `..`、符号链接、路径穿越）。
///
/// 拆成纯函数便于单测：路径判定是安全边界，必须能在不进文件系统/不起 Tauri 的
/// 情况下断言（见 tests）。
fn ensure_within_updates_dir(
    canonical: &std::path::Path,
    updates_real: &std::path::Path,
) -> Result<(), String> {
    // `Path::starts_with` 只按组件前缀比较、不做归一化：`updates/../evil.exe` 会被
    // 判为位于 `updates` 下。调用方已 canonicalize（不含 `..`），这里再显式拒绝
    // `..` 组件，避免将来有人拿未归一的路径调用它而绕过目录边界。
    let has_parent_dir = canonical
        .components()
        .any(|component| matches!(component, std::path::Component::ParentDir));
    if has_parent_dir || !canonical.starts_with(updates_real) {
        log::error!(
            "Rejecting installer outside updates dir: {} (root {})",
            canonical.display(),
            updates_real.display()
        );
        return Err(
            "UPDATE_PATH_REJECTED: installer path is outside updates directory".to_string(),
        );
    }
    Ok(())
}

/// 校验安装包路径：必须是 `AppData/updates/` 目录内的真实文件，并返回其规范化路径。
///
/// 安全边界：任意路径、绝对/相对遍历、`..`、指向目录外的符号链接都会拒绝，
/// 避免被伪装的 frame 或插件利用去执行任意文件。
fn resolve_installer_path(app_handle: &AppHandle, path: &str) -> Result<PathBuf, String> {
    let updates_dir = updates_dir(app_handle)?;
    let p = std::path::Path::new(path);
    if !p.exists() || !p.is_file() {
        return Err(format!("UPDATE_NOT_FOUND: {path}"));
    }
    // 规范化后必须仍在 updates 目录内。用 `dunce::canonicalize`（std
    // `fs::canonicalize`）——它返回的路径不带 Windows `\\?\` verbatim 前缀，
    // `starts_with` 与日志展示更一致。
    let canonical = dunce::canonicalize(p).map_err(|e| format!("UPDATE_OPEN: {e}"))?;
    let updates_real = dunce::canonicalize(&updates_dir).map_err(|e| format!("UPDATE_DIR: {e}"))?;
    ensure_within_updates_dir(&canonical, &updates_real)?;
    Ok(canonical)
}

/// 是否为 AppImage 安装包（Linux 便携格式，自带运行时可执行）。
#[cfg(target_os = "linux")]
fn is_appimage(path: &std::path::Path) -> bool {
    path.extension()
        .is_some_and(|ext| ext.eq_ignore_ascii_case("AppImage"))
}

/// 校验安装包并交给系统默认处理器打开（不停服务、不动「待安装」标记）。
///
/// **调用方必须先停 Harness**（见 [`stop_for_installer`](crate::service::workflow::stop_for_installer)）：
/// 安装器会强杀桌面端进程，桌面端先消失就没人回收 Harness 子进程，它变成孤儿继续
/// 占用配置端口，更新后的新实例会撞上 EADDRINUSE。两条调用路径各自完成停服：
/// 「对话框立即更新」用 async 的 `workflow::stop`（要更新状态），「退出时自动更新」
/// 用同步的 `stop_for_installer`（退出路径没有 async 运行时可用）。停止动作不放在
/// 这里，是为了让每条路径都能按自己的时序等待端口释放。
pub(super) fn open_installer_now(app_handle: &AppHandle, path: &str) -> Result<(), String> {
    let resolved = resolve_installer_path(app_handle, path)?;
    log::info!("Opening desktop installer: {}", resolved.display());
    // 兜底补充可执行权限：兼容老版本下载的 AppImage（0644）被打包用户留存，
    // 直接打开仍会失败；此处幂等修复后再交给系统处理器。
    #[cfg(unix)]
    ensure_installer_executable(&resolved)?;

    // Linux：AppImage 自带运行时，直接执行；xdg-open 依赖桌面注册的 MIME
    // 处理器，COSMIC 等未注册的环境会静默失败（open::that_detached 只检查
    // 进程是否 spawn 成功，看不到 xdg-open 的退出码）。.deb/.rpm 仍交给系统
    // 默认处理器（软件中心 / 包管理器）。
    #[cfg(target_os = "linux")]
    if is_appimage(&resolved) {
        std::process::Command::new(&resolved)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .map_err(|e| format!("UPDATE_OPEN: {e}"))?;
        return Ok(());
    }

    app_handle
        .opener()
        .open_path(resolved.to_string_lossy(), None::<&str>)
        .map_err(|e| format!("UPDATE_OPEN: {e}"))
}

/// 打开安装包：交给系统默认处理器（Windows 会触发 UAC 执行安装器）。
pub async fn open_installer(app_handle: &AppHandle, path: String) -> Result<(), String> {
    if crate::managed::enabled() {return Err("Installer execution disabled by WhaleRealm".into());}
    // 更新前先停下本应用持有的 Harness 服务：安装器在安装时会强杀桌面端进程
    // （CheckIfAppIsRunning → taskkill），跳过正常退出路径的 stop_on_exit，导致
    // Harness 子进程变成孤儿继续占用配置端口。若此刻不提前停掉，更新后新实例
    // 启动会撞上 EADDRINUSE（旧 Harness 仍占着端口），表现为「更新后进不去」。
    // 提前停止 → 端口释放并清掉 .harness.pid 标记，更新后启动即可绑定原端口。
    // 仅在确有持有进程时才停（stop 在无持有进程时也会短暂等待端口释放，白耗
    // 约 0.8s）；停止失败只告警不阻断——它是避免端口冲突的辅助手段，打开失败
    // 另有 UPDATE_OPEN 的错误提示。
    if workflow::has_owned_process() {
        if let Err(e) = workflow::stop(app_handle.clone()).await {
            log::warn!("Failed to stop Harness before opening installer: {}", e);
        }
    }
    open_installer_now(app_handle, &path)?;
    // 安装包已交给系统 → 清除「待安装」标记，避免退出应用时重复拉起安装器。
    super::pending::set(app_handle, None);

    // Linux AppImage 安装包就是新版本本体，且与当前实例共用单实例 D-Bus 锁：
    // 当前实例不退出时，新进程会转发激活后立即退出（表现为「打开安装包」无效）。
    // 释放单实例名并退出，让已拉起的新版本接管；.deb/.rpm 由包管理器处理，
    // 无需结束当前实例。
    #[cfg(target_os = "linux")]
    if is_appimage(std::path::Path::new(&path)) {
        tauri_plugin_single_instance::destroy(app_handle);
        app_handle.exit(0);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// 下载后补充可执行位：下载默认 0644 的文件被修复为含可执行位（issue #79）。
    #[cfg(unix)]
    #[test]
    fn ensure_installer_executable_sets_exec_bit() {
        use std::os::unix::fs::PermissionsExt;
        let dir = std::env::temp_dir().join(format!("dsh-update-exec-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("installer.AppImage");
        std::fs::write(&file, b"payload").unwrap();
        // 模拟下载默认权限 0644
        std::fs::set_permissions(&file, std::fs::Permissions::from_mode(0o644)).unwrap();
        ensure_installer_executable(&file).unwrap();
        let mode = std::fs::metadata(&file).unwrap().permissions().mode();
        assert_eq!(
            mode & 0o111,
            0o111,
            "应包含所有者/组/其他可执行位，mode={mode:o}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// AppImage 识别按扩展名匹配且大小写不敏感；其它安装包格式不受影响。
    #[cfg(target_os = "linux")]
    #[test]
    fn appimage_detection_is_extension_based() {
        use std::path::Path;
        assert!(is_appimage(Path::new(
            "/tmp/Deepseek.Harness.Desktop_0.13.0_amd64.AppImage"
        )));
        assert!(is_appimage(Path::new("/tmp/tool.appimage")));
        assert!(!is_appimage(Path::new(
            "/tmp/Deepseek.Harness.Desktop_0.13.0_amd64.deb"
        )));
        assert!(!is_appimage(Path::new(
            "/tmp/Deepseek.Harness.Desktop_0.13.0_x86_64.rpm"
        )));
        assert!(!is_appimage(Path::new("/tmp/AppImage")));
    }

    /// 镜像兜底策略回归：无摘要时只有官方源；有摘要时才加入镜像。
    #[test]
    fn download_sources_only_mirrors_with_digest() {
        let url = "https://github.com/x/y/releases/download/v0.7.4/x.dmg";
        let base = LatestRelease {
            version: "0.7.4".into(),
            tag: "v0.7.4".into(),
            published_at: String::new(),
            url: url.into(),
            asset_name: "x.dmg".into(),
            digest: None,
        };
        // 无摘要 → 仅官方直连
        let without = download_sources(&base);
        assert_eq!(without.len(), 1);
        assert_eq!(without[0], url);
        // 有摘要 → 官方 + 镜像
        let with_digest = LatestRelease {
            digest: Some(format!("sha256:{}", "b".repeat(64))),
            ..base.clone()
        };
        let sources = download_sources(&with_digest);
        assert_eq!(sources.len(), 2);
        assert!(
            sources[1].contains("ghfast.top"),
            "镜像应为 ghfast.top 前缀: {}",
            sources[1]
        );
        assert!(
            sources[1].ends_with("/releases/download/v0.7.4/x.dmg"),
            "镜像保留完整资产路径: {}",
            sources[1]
        );
    }

    /// 流式校验：正确的文件通过、错误的摘要拒绝，且不把整个文件读进内存。
    #[test]
    fn verify_installer_sha256_streams_and_rejects_mismatch() {
        use sha2::Digest;
        let dir = std::env::temp_dir().join(format!("dsh-update-hash-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("installer.part");
        let content = b"deepseek-harness-desktop installer payload";
        std::fs::write(&file, content).unwrap();
        let real = format!("sha256:{:x}", sha2::Sha256::digest(content));
        // 正确摘要通过
        assert!(verify_installer_sha256(&file, &real).is_ok());
        // 裸 64hex（无 sha256: 前缀）也接受
        assert!(verify_installer_sha256(&file, real.trim_start_matches("sha256:")).is_ok());
        // 错误摘要拒绝
        let wrong = format!("sha256:{}", "0".repeat(64));
        assert!(verify_installer_sha256(&file, &wrong).is_err());
        // 非法摘要格式拒绝
        assert!(verify_installer_sha256(&file, "sha256:zz").is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// 安装包路径必须是 updates 目录内的文件：同前缀的兄弟目录、目录穿越都拒绝。
    /// 退出时自动打开安装器（pending）与对话框「打开安装包」共用这条判定。
    #[test]
    fn ensure_within_updates_dir_rejects_outside_paths() {
        let root = std::path::Path::new("root").join("updates");
        // 目录内 → 通过
        assert!(ensure_within_updates_dir(&root.join("app-setup.exe"), &root).is_ok());
        // 目录外的兄弟路径（前缀相同也不能放过：`updates-evil` 不是 `updates` 的子路径）
        assert!(ensure_within_updates_dir(&root.join("..").join("evil.exe"), &root).is_err());
        let sibling = std::path::Path::new("root")
            .join("updates-evil")
            .join("x.exe");
        assert!(ensure_within_updates_dir(&sibling, &root).is_err());
    }
}

//! 「安装包已下载、等待安装」标记与退出时自动更新。
//!
//! 需求链路：桌面端检测到新版本后**静默下载**（不弹右下角 toast）；用户可能不
//! 立刻安装，于是在**关闭应用**时自动打开已下载的安装器，避免用户错过升级。
//!
//! 标记存在 store 的独立键（`STORE_PENDING_INSTALLER_KEY`）而非 `Setting` 字段：
//! `Setting` 会被前端整对象写回（`bridge::config` / `bridge::lifecycle`），运行期
//! 标记不能被前端 payload 覆盖。下载成功即置位，用户真正打开安装包（对话框
//! 「打开安装包」或退出时自动打开）后清除。

use std::path::Path;

use serde::{Deserialize, Serialize};
use tauri::AppHandle;
use tauri_plugin_store::StoreExt;

use crate::config::{store_dat_file_name, STORE_PENDING_INSTALLER_KEY};
use crate::service::workflow;

/// 「待安装」标记：安装包路径 + 它对应的版本号。
///
/// 记版本号是为了退出时的**版本护栏**（见 [`launch_pending_installer`]）：
/// 用户可能用别的方式（手动下载/包管理器）升级到了更新的版本，此时绝不能拿
/// 手里的旧安装包在退出时把它降级安装掉。
#[derive(Debug, Clone, Serialize, Deserialize)]
struct PendingInstaller {
    path: String,
    version: String,
}

/// 读取「待安装」标记；无标记、内容非法或路径为空时返回 `None`。
fn get(app_handle: &AppHandle) -> Option<PendingInstaller> {
    let store = app_handle.store(store_dat_file_name()).ok()?;
    let value = store.get(STORE_PENDING_INSTALLER_KEY)?;
    let pending: PendingInstaller = serde_json::from_value(value).ok()?;
    if pending.path.is_empty() {
        return None;
    }
    Some(pending)
}

/// 记录 / 清除「待安装」标记（`None` = 已安装，或无需退出时自动打开）。
///
/// 失败只告警不阻断：标记只是「退出时自动更新」的辅助，丢掉它的降级态是用户
/// 需要在对话框里手动点一次「打开安装包」，不该让下载/打开流程随之失败。
pub(super) fn set(app_handle: &AppHandle, pending: Option<(&Path, &str)>) {
    let Ok(store) = app_handle.store(store_dat_file_name()) else {
        log::warn!("Failed to load store for pending installer marker");
        return;
    };
    match pending {
        Some((path, version)) => {
            let value = serde_json::json!({
                "path": path.to_string_lossy(),
                "version": version,
            });
            store.set(STORE_PENDING_INSTALLER_KEY, value);
        }
        None => {
            store.delete(STORE_PENDING_INSTALLER_KEY);
        }
    }
    if let Err(error) = store.save() {
        log::warn!("Failed to save pending installer marker: {error}");
    }
}

/// 应用退出时自动打开已下载的待安装包。
///
/// 只在「已下载但用户没在应用内打开过」时触发（标记由 `install` 模块维护）。
/// 同步、不触网：退出路径不能引入等待或网络请求，把安装包交给系统默认处理器
/// 启动即可（Windows 会触发 UAC，macOS/Linux 交给各自的系统安装流程）。
pub fn launch_pending_installer(app_handle: &AppHandle) {
    if crate::managed::enabled() {return;}
    let Some(pending) = get(app_handle) else {
        return;
    };
    // 先清标记：无论本次能否成功打开，都不在后续退出时反复尝试——用户已经明确
    // 退出应用，反复拉起安装器只会变成打扰；降级态是用户自己在对话框里手动安装。
    set(app_handle, None);

    // 版本护栏：待安装包必须严格新于当前运行版本。用户若已用别的方式升到更新的
    // 版本（手动下载/包管理器），此刻拉起旧安装包会变成降级安装。
    let current = super::version::current_version();
    if !super::version::is_newer(&pending.version, &current) {
        log::info!(
            "Pending installer {} is not newer than running {current}, skipping auto update",
            pending.version
        );
        return;
    }

    log::info!(
        "Launching pending desktop installer on exit: {} ({})",
        pending.path,
        pending.version
    );
    // 打开安装包前先停 Harness：安装器会强杀桌面端进程，桌面端先消失就没人回收
    // Harness 子进程，它会变成孤儿继续占用配置端口，更新后新实例撞 EADDRINUSE。
    // 退出路径虽已调过 stop_on_exit，但那份保障依赖调用方顺序与 `setting.installed`
    // 门槛；自动更新是「用安装器替换本应用」的场景，停服必须由交付点自己保证（幂等，
    // 重复调用只是 no-op）。
    workflow::stop_for_installer(app_handle);
    if let Err(error) = super::install::open_installer_now(app_handle, &pending.path) {
        log::warn!("UPDATE_OPEN: failed to launch pending installer on exit: {error}");
    }
}

//! 安装环境（Node.js 运行时 + 打包的 Harness 发行版 + pnpm；Windows 缺失
//! 系统 Git 时再自动安装免安装 MinGit）。原 `workflow::install`。

use crate::config;
use crate::service::download;
use crate::service::download::Installable;
use tauri::Manager;

use super::process::{has_owned_process, stop, terminate_stale_harness_processes};

/// 安装环境（Node.js 运行时 + 打包的 Harness 发行版 + pnpm；Windows 缺失
/// 系统 Git 时再自动安装免安装 MinGit）。
///
/// 返回是否真正落盘更新了 Harness（dsh 任务实际下载并解压）；仅重装
/// Node/pnpm/Git 或全部任务被跳过时返回 false，供调用方决定是否重启页面。
pub async fn install(
    app_handle: &tauri::AppHandle,
    mut dsh_latest: Option<download::LatestDshPkg>,
) -> Result<bool, String> {
    if crate::managed::enabled() {return Err("Runtime replacement requires a certified WhaleRealm deployment".into());}
    log::info!("Starting installation process");
    // dsh 任务实际下载解压时置 true
    let mut dsh_updated = false;

    // 安装前先停止本应用持有的 Harness 服务：运行中的 node 进程会把
    // 原生模块 DLL（如 sharp 的 libvips-42.dll）加载进内存并锁住文件，
    // 不停止的话覆盖解压必然失败（Windows os error 32）。
    // 进程归属以启动时记录的 PID 为准，不根据端口结束未知程序。
    if has_owned_process() {
        log::info!("Stopping running Harness service before installation");
        stop(app_handle.clone()).await?;
    }
    // 只停本应用持有的进程还不够：历史崩溃/强杀残留的孤儿 Harness 实例
    // （不在 .harness.pid 标记中）同样从 dependencies/dsh 启动、占用目录文件
    // 句柄，会导致更新切换目录失败（INSTALL_BACKUP_FAILED, os error 32）。
    // 按命令行路径精确清扫所有本应用 dsh 安装目录启动的进程。
    // 枚举/结束涉及 powershell 枚举与 taskkill（同步阻塞），移出 Tokio 线程。
    {
        let handle = app_handle.clone();
        tauri::async_runtime::spawn_blocking(move || {
            terminate_stale_harness_processes(&handle);
        })
        .await
        .map_err(|e| format!("STOP_FAILED: {e}"))?;
    }

    let window = app_handle
        .get_webview_window("main")
        .ok_or("Failed to get main window")?;
    log::debug!("Main window obtained");
    // 依赖任务清单的唯一构造点在下载层，安装流程与映射回写共用同一组任务。
    let tasks = download::tasks();
    // 必须在下载前解析 release 元数据：下载地址和摘要必须属于同一固定 tag。
    // 若先下载 latest、再因 API 限流从 Atom/HTML 解析 tag，latest 在两次请求间
    // 发生切换就会把另一份资产拿来匹配摘要，最终触发 INTEGRITY_CHECK_FAILED。
    let dsh_missing = !download::Dsh.check_installed(app_handle);
    if dsh_latest.is_none() && dsh_missing {
        for attempt in 0..3 {
            let metadata = match config::recommended_dsh_version(app_handle) {
                Some(version) => download::fetch_dsh_pkg_version(&version).await,
                None => download::fetch_latest_dsh_pkg_info().await,
            };
            match metadata {
                Ok(info) => {
                    dsh_latest = Some(info);
                    break;
                }
                Err(e) if attempt < 2 => {
                    log::warn!(
                        "Retrying dsh release metadata fetch ({}/3), will retry: {}",
                        attempt + 1,
                        e
                    );
                    tokio::time::sleep(std::time::Duration::from_millis(
                        500 * (attempt as u64 + 1),
                    ))
                    .await;
                }
                Err(e) => {
                    return Err(format!(
                        "DSH_INTEGRITY_UNAVAILABLE: 无法获取 Harness 发行版的完整性校验信息（{}），请检查网络后重试",
                        e
                    ));
                }
            }
        }
    }
    // Windows Sandbox 等空白环境没有 Git；仅 Windows 加入第 4 项，若系统 Git
    // 可真实执行则 Installable 会跳过，不重复下载也不修改系统 PATH。
    // 每项均有下载/解压两个阶段，按实际平台任务数计算，避免进度提前到 100%。
    let mut tracker = download::ProgressTracker::new(&window, tasks.len() * 2);
    log::info!("Task list created, {} tasks total", tasks.len());

    for (index, task) in tasks.iter().enumerate() {
        let kind = task.kind();
        log::debug!("Processing task {}/{}", index + 1, tasks.len());
        // 已安装但版本/commit 与最新 release 不一致时强制重新下载。
        // 版本优先（与 resolve_update 的判定完全一致）：dsh 的 rc 发布会复用
        // 同一 git commit（record_commit 不变），只比 commit 会把 rc.8 之于
        // rc.7 误判为"已最新"而跳过下载——日志表现为"All installation tasks
        // completed"但实际什么都没下载，重启后仍是旧版，且前端丢掉更新提示。
        let outdated = kind == download::InstallKind::Dsh
            && dsh_latest.as_ref().is_some_and(|info| {
                let installed_version = config::get_dsh_version(app_handle);
                let latest_version = download::parse_version_from_tag(&info.tag);
                // 版本号可解析且不同 → 必须更新；版本不可解析时退回同一发布判定
                let version_differs =
                    match (installed_version.as_deref(), latest_version.as_deref()) {
                        (Some(a), Some(b)) => a != b,
                        _ => false,
                    };
                // 「同一发布」判定与 resolve_update 完全一致：记录 tag 与最新 tag
                // 相同、或记录 commit 与 release 的任一合法标识（完整 SHA / build-id）
                // 一致。限流期安装会把 build-id 写进记录，API 恢复后解析出的完整
                // SHA 与之不等但仍是同一 release，不能据此误判为过期而重下。
                version_differs
                    || !download::record_matches_latest_release(
                        config::get_dsh_pkg_commit(app_handle).as_deref(),
                        config::get_dsh_pkg_tag(app_handle).as_deref(),
                        info,
                    )
            });
        if task.check_installed(app_handle) && !outdated {
            log::debug!(
                "Task {} already installed and up to date, skipping",
                index + 1
            );
            // 已就绪也要落映射：系统环境满足记 `null`，托管版记安装根。
            task.record_mapping(app_handle);
            tracker.skip_phases(2);
            continue;
        }

        log::info!("Task {} not installed, starting installation", index + 1);

        // 1. 下载
        tracker.start_phase(
            "download",
            &format!(
                "{} {}",
                config::i18n::t("install.downloading"),
                task.title()
            ),
        );
        // 下载 URL 对 dsh 也是完全确定可算的（DSH_CORE_URL + 平台文件名），
        // 无需依赖 GitHub API 元数据；api.github.com 限流/被代理拦截时
        // （mac 首次启动常见）仍能拿到真实下载地址，避免整次安装被瞬时失败卡死。
        // dsh 核心默认先走 GitHub 官方直连，失败自动切换 ghfast.top 镜像兜底
        // （下载层会在界面上告知用户）；其余任务保持单一官方源。
        let (urls, name) = if kind == download::InstallKind::Dsh {
            // 摘要与资产必须来自同一个 release。若前面已取得 release 元数据，
            // 必须使用其中的固定 asset URL；继续请求 `releases/latest` 会在 latest
            // 发布切换或 CDN 缓存不一致时下载另一份文件，最终表现为摘要 mismatch。
            let primary = dsh_latest
                .as_ref()
                .map(|info| info.asset_url.clone())
                .filter(|url| !url.is_empty())
                .unwrap_or(config::get_dsh_download_url()?);
            let name = primary.rsplit('/').next().unwrap_or("").to_string();
            let urls = vec![primary.clone(), config::mirror_download_url(&primary)];
            (urls, name)
        } else {
            let url = task.get_download_url()?;
            let name = url.rsplit('/').next().unwrap_or("").to_string();
            (vec![url], name)
        };
        // 取文件名用于解压类型判定；下载 URL 正常必含 '/'，但这里不 panic，
        // 防御性兜底为空串（后续 ensure_extract 会因无法判定类型而报错返回，
        // 不再让进程崩溃）。
        log::debug!("Download URL: {}", urls.join(" -> "));
        log::debug!("File name: {}", name);
        let buffer = download::download_file_from_sources(&tracker, urls).await?;
        log::info!("Download completed, file size: {} bytes", buffer.len());
        let expected_digest = match kind {
            download::InstallKind::Node => {
                download::fetch_node_sha256(task.get_download_url()?.as_str()).await?
            }
            download::InstallKind::Dsh => {
                // 元数据已在安装任务开始前获取，确保下载地址与摘要来自同一 release。
                dsh_latest
                    .as_ref()
                    .and_then(|info| info.digest.clone())
                    .ok_or_else(|| {
                        "DSH_INTEGRITY_UNAVAILABLE: trusted release digest is required".to_string()
                    })?
            }
            download::InstallKind::Pnpm => config::PNPM_SHA256.to_string(),
            #[cfg(windows)]
            download::InstallKind::Git => config::get_mingit_sha256()?.to_string(),
            #[cfg(not(windows))]
            download::InstallKind::Git => {
                return Err(
                    "INSTALL_TASK_INVALID: Git task not supported on this platform".to_string(),
                )
            }
        };
        download::verify_sha256(&buffer, &expected_digest)?;
        log::info!("Download integrity verified for task {}", index + 1);
        tracker.end_phase();

        // 2. 解压
        tracker.start_phase(
            "extract",
            &format!("{} {}", config::i18n::t("install.extracting"), task.title()),
        );
        let dest = task.get_install_path(app_handle);
        log::debug!("Installation path: {:?}", dest);
        download::ensure_extract(&tracker, name, buffer, dest).await?;
        log::info!("Extraction completed");
        // 解压落盘即建立该依赖的路径映射（新用户 / 缺少内核的场景）。
        task.record_mapping(app_handle);
        tracker.end_phase();

        // 记录本次安装对应的 release tag 与 commit，供下次启动比对
        if kind == download::InstallKind::Dsh {
            dsh_updated = true;
            if let Some(info) = &dsh_latest {
                config::set_dsh_pkg_identity(app_handle, info.commit.clone(), info.tag.clone());
            }
        }
    }

    log::info!("All installation tasks completed");
    tracker.update(
        100.0,
        config::i18n::t("install.done"),
        "All tasks completed".into(),
    );

    Ok(dsh_updated)
}

//! Harness 服务启动编排：`start` / `restart` / `launch`，含端口自愈
//! （避让递增 + 回落、等待释放）、补丁挂点与 Windows 隐藏控制台启动。

use crate::config;
use std::collections::HashMap;
use std::ffi::OsString;
use std::fs;
use std::path::Path;
#[cfg(not(windows))]
use std::io::Read;
#[cfg(not(windows))]
use std::process::{Command, Stdio};
use std::sync::atomic::Ordering;

#[cfg(not(windows))]
use super::process::set_owned_process;
#[cfg(windows)]
use super::process::set_owned_process_with_handle;
#[cfg(unix)]
use super::process::warn_if_inotify_watch_limit_low;
use super::process::{
    has_owned_process, on_owned_process_exit, stop, terminate_stale_harness_processes, LaunchGuard,
    LAUNCH_GUARD,
};
use super::status;
use super::sweep::persist_harness_pid;
#[cfg(windows)]
use super::sweep::{dsh_bin_open_error, relaunch_marker_path, relaunch_via_shell_escape};
use super::utils::{is_port_in_use, rotate_service_log, spawn_output_readers};
use super::win_inspector;

#[cfg(windows)]
type SpawnResult = std::io::Result<(Option<std::fs::File>, Option<std::fs::File>, u32)>;
#[cfg(unix)]
type SpawnResult = Result<
    (
        Option<std::process::ChildStdout>,
        Option<std::process::ChildStderr>,
        u32,
    ),
    String,
>;

/// 端口释放等待上限：刚结束/清扫过上个会话的残留 dsh 进程后，TCP 端口释放
/// 存在短暂滞后（taskkill 返回 ≠ 端口已可复用）。等待窗口内端口回落为空闲则
/// 复用配置端口；到期仍未释放才按“真占用”逐级递增。
const PORT_RELEASE_WAIT: std::time::Duration = std::time::Duration::from_millis(1500);

fn build_harness_args(dsh_binary: &Path, profile: &str, port: u16, heap_mb: Option<u32>) -> Vec<OsString> {
    let mut args = Vec::with_capacity(9);
    args.extend(super::heap::heap_option_arg(heap_mb));
    args.extend([
        dsh_binary.as_os_str().to_os_string(),
        OsString::from("--profile"),
        OsString::from(profile),
        // The dsh launcher owns only --profile/--patch/--dump-*; the first token it
        // does not recognise starts the inner app arguments (see @deepseek-ai/dsh/args,
        // passThroughOptions + enablePositionalOptions). --patch must precede
        // --port/--no-open, otherwise it is handed verbatim to the booted app, which
        // rejects it as an unknown option.
        OsString::from("--patch"),
        crate::managed::path("data/dsh-home/managed-desktop.patch.yml").into_os_string(),
        OsString::from("--port"),
        OsString::from(port.to_string()),
        OsString::from("--no-open"),
    ]);
    args
}

/// 轮询等待配置端口释放为空闲（端口本来就空闲则立即返回）。
///
/// async（tokio）实现，避免长时间阻塞启动线程。与 `stop()` 里“给系统一点时间
/// 释放端口”的目的一致，但以“端口确实空闲”为准而不是固定睡 800ms——因此
/// 端口很快释放时几乎不额外耗时，只有真占用才等到超时。
async fn wait_for_port_release(port: u16) {
    let deadline = tokio::time::Instant::now() + PORT_RELEASE_WAIT;
    while tokio::time::Instant::now() < deadline {
        if !is_port_in_use(port) {
            return;
        }
        tokio::time::sleep(std::time::Duration::from_millis(80)).await;
    }
}

/// 从起始端口向上查找第一个空闲端口，绝不结束未知的端口占用进程。
fn find_available_port(start: u16) -> Result<u16, String> {
    find_available_port_by(start, is_port_in_use)
}

/// 按调用方提供的占用判定查找第一个空闲端口。
///
/// 将扫描决策与真实套接字状态分离，使单测能确定性验证递增与溢出，不在函数
/// 返回后再次探测系统端口；后者存在不可消除的 TOCTOU，任何端口段都可能被
/// 其他进程在两次探测之间占用。
fn find_available_port_by(
    start: u16,
    mut is_in_use: impl FnMut(u16) -> bool,
) -> Result<u16, String> {
    let mut port = start;
    loop {
        if !is_in_use(port) {
            return Ok(port);
        }
        log::warn!("Port {port} is occupied, trying the next port");
        port = port.checked_add(1).ok_or_else(|| {
            "PORT_EXHAUSTED: no available TCP port after the configured port".to_string()
        })?;
    }
}

/// 启动时端口自愈决策（纯函数，便于单测）。
///
/// 自动避让递增（配置端口被占 → 逐级顶高）遗留的非默认端口只在回落目标
/// （用户手动端口或默认端口）空闲时才回落；回落目标被占则维持当前端口，
/// 留给 `find_available_port` 逐级递增。用户手动设置的端口经 `manual_port`
/// 记录，回落目标即用户值；从未手动设置时回落目标是默认端口（3080/3081）。
/// 返回值与 `configured` 相同表示无需自愈。
fn resolve_heal_port(configured: u16, heal_target: u16, heal_target_free: bool) -> u16 {
    if configured != heal_target && heal_target_free {
        heal_target
    } else {
        configured
    }
}

/// 检测并启动 Harness 服务
pub async fn start(app_handle: tauri::AppHandle) -> Result<(), String> {
    let setting = config::get_store_dat_setting(&app_handle);
    let node_binary_path = config::get_node_binary_path(&app_handle);
    // 活动核心的入口：本地核心存在时优先本地（需求 3），否则预打包
    let dsh_binary_path = crate::service::core::active_dsh_binary(&app_handle);

    if !setting.installed {
        log::debug!("Harness not installed, skipping startup");
        return Ok(());
    }
    if !node_binary_path.exists() || !dsh_binary_path.exists() {
        // Windows RedirectionGuard(448)：安装器继承的强制执行上下文永不自行恢复，
        // 先尝试通过 explorer 逃逸重拉（见 relaunch_via_shell_escape 注释），
        // 成功则本进程退出；未命中（重拉未逃逸/非 448）才走常规缺失处理。
        #[cfg(windows)]
        if dsh_bin_open_error(&app_handle) == Some(448) {
            relaunch_via_shell_escape(&app_handle);
        }
        let mut setting = config::get_store_dat_setting(&app_handle);
        setting.installed = false;
        config::set_store_dat_setting(&app_handle, setting);
        // 状态变更需要 info 级落盘：这是「store 显示未安装」的源头之一
        // （核心文件短暂缺失被复位），自更新后自动重开走进安装分支多由此触发。
        log::info!("Runtime files missing (node/dsh), resetting installed flag");
        return Ok(());
    }

    if has_owned_process() {
        log::info!("Owned Harness process is already running");
        status::set_status(status::Status::Running);
        status::emit_status(&app_handle);
        return Ok(());
    }

    // 清理 RedirectionGuard(448) 逃逸重拉标记：本进程正常走到启动说明处于干净上下文，
    // 移除标记保证下次自更新后仍能触发逃逸重拉。
    #[cfg(windows)]
    let _ = std::fs::remove_file(relaunch_marker_path(&app_handle));

    log::info!("Starting Harness service");
    status::set_status(status::Status::Starting);
    status::emit_status(&app_handle);
    launch(app_handle).await?;
    // 之后由 scheduler/task/tick_check_dsh_process/mod.rs 检测状态

    Ok(())
}

/// 重启 Harness 服务
pub async fn restart(app_handle: tauri::AppHandle) -> Result<(), String> {
    log::info!("Restarting Harness service");

    // 1. 停止现有服务
    stop(app_handle.clone()).await?;

    // 2. 重新启动
    start(app_handle).await?;

    Ok(())
}

/// 把 active profile 的 `cordis.yml` 重置为官方空根。
///
/// dsh 的 Loader 在插件 dispose 时会把组合后的整棵 entry 树回写进
/// `cordis.yml`（dsh-app-boot：plugin self-disposing persists the current
/// tree）。上一轮被杀/崩溃的 dsh 若留下组合行，新 boot 会读到已含 bundle 行的
/// 文件，再叠加同一批 patch → `duplicate loader entry`。spawn 前与「早期退出
/// 重试」各调用一次，把竞态窗口关闭到最小；文件已是空根时静默跳过。
fn reset_active_profile_root(app_handle: &tauri::AppHandle) {
    let profile_root = crate::service::profile::profile_dir_of(
        app_handle,
        &crate::service::profile::active_profile(app_handle),
    );
    if !profile_root.is_dir() {
        return;
    }
    let root_config = profile_root.join("cordis.yml");
    const PROFILE_ROOT_EMPTY: &str = "# dsh profile root — an empty entry list. The tree is composed as patches:\n# each bundle in package.json's dsh.profile.bundles, then cordis.patch.yml, then any\n# --patch overlays. Edit cordis.patch.yml, not this file.\n[]\n";
    if std::fs::read_to_string(&root_config).ok().as_deref() != Some(PROFILE_ROOT_EMPTY) {
        if let Err(e) = std::fs::write(&root_config, PROFILE_ROOT_EMPTY) {
            log::warn!("PROFILE_ROOT_RESET_FAILED: {}: {e}", root_config.display());
        } else {
            log::info!(
                "Reset stale profile root before spawn: {}",
                root_config.display()
            );
        }
    }
}

/// 判断 dsh 早期退出是否命中「duplicate loader entry」竞态签名。
///
/// 竞态特征：exit code 1 且 stderr 含 `duplicate loader entry`（dsh-app-boot
/// 的 Include 把重复 bundle 行叠加进根树时抛出的 TypeError 文本，实测
/// `duplicate loader entry id: dsh-tauri-worktree`）。
#[cfg(windows)]
fn is_duplicate_loader_exit(exit_code: u32, stderr: &str) -> bool {
    exit_code == 1 && stderr.contains("duplicate loader entry")
}

/// 启动 Harness 服务进程
pub async fn launch(app_handle: tauri::AppHandle) -> Result<(), String> {
    // 启动分段计时（issue #766）：只写日志，不改控制流。每段一行 `STARTUP_PHASE`，
    // `ms` 是本段耗时、`total` 是本次 launch 的累计耗时。启动慢的归因过去只能靠
    // 时间戳猜测（同一进程内 auto_start 与前端 invoke 并发交错），埋点后可直接
    // 从 desktop.log 读出「哪一段慢、慢多少」。
    let startup_started = std::time::Instant::now();
    let mut phase_started = startup_started;
    // 段末打点：`ms` 为上一段耗时，`total` 为 launch 累计。closure 只服务本函数，
    // 因此就地定义而不抽成独立模块/工具。
    let mark_phase = |name: &str, phase_started: &mut std::time::Instant| {
        let now = std::time::Instant::now();
        log::info!(
            "STARTUP_PHASE: name={name} ms={} total={}",
            now.duration_since(*phase_started).as_millis(),
            now.duration_since(startup_started).as_millis()
        );
        *phase_started = now;
    };
    let mut setting = config::get_store_dat_setting(&app_handle);
    let node_binary_path = config::get_node_binary_path(&app_handle);
    let _transition_guard = super::process::acquire_core_transition().await?;
    let dsh_binary_path = crate::service::core::active_dsh_binary(&app_handle);

    log::debug!("Checking Node.js path: {:?}", node_binary_path);
    if !node_binary_path.exists() {
        log::error!("Node.js not installed");
        return Err("NODE_NOT_FOUND: Node.js not installed".to_string());
    }
    log::debug!("Checking Harness path: {:?}", dsh_binary_path);
    if !dsh_binary_path.exists() {
        log::error!("Harness not installed");
        return Err("HARNESS_NOT_FOUND: Harness not installed".to_string());
    }
    mark_phase("resolve", &mut phase_started);

    // 从这里开始持有与核心切换共用的互斥锁：最终状态检查、启动守卫、残留清扫
    // 及新进程登记必须处于同一临界区，避免切换在检查后插入。

    // 避免重复启动（配合启动守卫，确保并发调用只拉起一个进程）
    if has_owned_process() {
        log::info!("Owned Harness process is already running, skipping launch");
        return Ok(());
    }
    if LAUNCH_GUARD
        .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
        .is_err()
    {
        log::info!("Harness launch already in progress, skipping");
        return Ok(());
    }
    let _launch_guard = LaunchGuard;
    // 只有持有启动守卫的这条路径清扫残留：并发启动的其它调用已在守卫处返回，
    // 不会误杀刚拉起的进程。崩溃/强杀残留的孤儿 Harness 实例（不在
    // .harness.pid 标记中）持续占用配置端口与 dependencies/dsh 的文件句柄，
    // 不清扫会导致端口一路漂移（3080→…→3085，issue #91）并让后续目录互换
    // 失败（os error 32）。按命令行路径精确匹配本应用 dsh 服务，不会误杀
    // 用户其它 node 程序（debug 构建为 no-op，见 terminate_stale_harness_processes）。
    {
        let handle = app_handle.clone();
        if let Err(e) = tauri::async_runtime::spawn_blocking(move || {
            terminate_stale_harness_processes(&handle);
        })
        .await
        {
            log::warn!(
                "failed to sweep stale Harness processes before launch at {}: {e}",
                dsh_binary_path.display()
            );
        }
    }

    // 端口自愈：自动避让递增（配置端口被占 → 逐级顶高）遗留的非默认端口，
    // 在回落目标（用户手动端口 manual_port，否则默认端口）空闲时回落，避免
    // 端口只增不减、一路从 3080 漂到 3084+（issue #91）。先于
    // wait_for_port_release 探测：既然放弃旧端口，就无需等它释放。
    let heal_target = setting.manual_port.unwrap_or(config::default_port());
    let healed_port = resolve_heal_port(setting.port, heal_target, !is_port_in_use(heal_target));
    if healed_port != setting.port {
        log::info!(
            "Harness port healed from {} back to {} (no longer occupied)",
            setting.port,
            healed_port
        );
        setting.port = healed_port;
        config::set_store_dat_setting(&app_handle, setting.clone());
    }

    // 端口冲突时从当前值开始逐个递增，并持久化最终选择供所有调用方复用。
    // 注意：上个会话的残留 dsh 进程刚被我们结束/清扫（sweep_orphan、stop、
    // stop_on_exit），TCP 端口释放存在短暂滞后——此刻立刻探测会把“刚释放的
    // 端口”误判为仍占用，从而把配置端口永久顶高（dev 热更新下 3081→3082→…
    // 一路漂移，表现为“端口持续累加 + 首次启动超时、刷新后恢复”）。先留出
    // 窗口等配置端口回落为空闲，再决定是否真的逐级递增。
    wait_for_port_release(setting.port).await;
    let available_port = if crate::managed::enabled() { if is_port_in_use(setting.port) {return Err("Managed reserved port occupied".into());} setting.port } else {find_available_port(setting.port)?};
    if available_port != setting.port {
        log::info!(
            "Harness port changed from {} to {} because the configured port is occupied",
            setting.port,
            available_port
        );
        setting.port = available_port;
        config::set_store_dat_setting(&app_handle, setting.clone());
    }
    mark_phase("stale_sweep_and_port", &mut phase_started);

    // 构造环境变量：隔离的 $DSH_HOME + 隐私默认（关闭遥测）
    //
    // 建目录 + 可写性预检（issue #466）：`~/.dsh` 属主不是当前用户时（典型：此前
    // 用 sudo 运行过 dsh，macOS 的 sudo 保留 $HOME），读得到、写不了——dsh 起来后
    // 必然崩在写 cordis.yml/settings.yaml 上，前端只能看到
    // 「Harness exited early: exit status: 1」，完全不可行动。这里提前阻断并给出
    // 可直接粘贴的 chown 指引。
    let dsh_home = config::get_dsh_data_path(&app_handle);
    crate::service::perm::ensure_dir_writable(&dsh_home, "DSH_HOME_MKDIR_FAILED")?;
    // 当前档案目录同样必须在 spawn 前可写：`$DSH_HOME` 可写不代表档案可写——属主
    // 错位可能只落在 `profiles` 或 `profiles/<id>` 上（安全模式要新建 `profiles/safe`，
    // 因此 `profiles` 不可写同样是致命状态）。
    //
    // 先跑一次档案迁移 + 首装引导（幂等）：desktop::setup 的引导若失败（磁盘/权限
    // 抖动）或本进程没进过 setup，这里兜底；改名必须早于可写性预检，否则预检拿到的
    // 还是改名前的档案目录。最佳努力：失败只告警，不阻断启动。
    crate::service::profile::migrate_desktop_profile_name(&app_handle);

    // 预检不创建目录，避免抢先建出半初始化档案（issue #452）。
    crate::service::perm::ensure_writable_path(
        &crate::service::plugin::profile_dir(&app_handle),
        &dsh_home,
        "PROFILE_NOT_WRITABLE",
    )?;

    // 核心 bundle 层自愈（issue #452）：当前档案的 `dsh.profile.bundles` 必须带
    // 桌面端内嵌 web UI 依赖的 `@deepseek-ai/dsh-base` + `@deepseek-ai/dsh-web-app`
    // （顺序即补丁层应用顺序）。档案目录被 CLI/外部初始化过（`dsh plugin add`
    // 对无清单目录只写 dsh-base）、首次初始化中途失败、用户手工编辑清单都会剥掉
    // web 层，此时宿主不提供 webServer/connection/webRuntime，内置插件与市场插件
    // 全部停在 pending，服务启动必然失败——日志只显示「N entries did not
    // activate / waiting for service: webServer」，看不出根因。缺失时按官方 web
    // 模板补齐（只补不删，用户插件条目原样保留），本轮启动即可恢复。必须在
    // 任何插件操作与 spawn 之前做。最佳努力：失败只告警，不阻断启动。
    if let Err(e) = crate::service::profile::ensure_active_profile_core_bundles(&app_handle) {
        log::warn!("ensure active profile core bundles failed: {e}");
    }

    // 安全模式：安全档案的契约是「只加载 web 模板核心 bundles、不带任何用户插件」，
    // 但档案目录一旦存在就绝不重建（用户可能反复进出安全模式），而内置插件自愈与
    // 首次引导安装都作用于「当时的活动档案」，于是安全档案里会累积用户插件——它们
    // 往往正是启动失败的元凶，不清干净的话每次进入安全模式都带着同一批插件重启，
    // 隔离形同虚设。必须在 spawn dsh 之前做（服务未运行时改清单、删 node_modules
    // 目录才安全）。内置插件与核心包由被调方保留；非安全档案直接跳过。最佳努力：
    // 失败只告警，不阻断启动（清理不彻底只是隔离效果打折，启动阻塞则让应用彻底不可用）。
    if let Err(e) = crate::service::plugin::purge_user_plugins_in_safe_profile(&app_handle) {
        log::warn!("safe mode user plugin purge failed: {e}");
    }
    mark_phase("profile_prepare", &mut phase_started);

    // Linux 起步前探测 inotify 监视上限：harness 服务（dsh web）用 chokidar 递归
    // 监视 profile 目录，上限过低会在启动一瞬间抛 ENOSPC 直接退出（issue #116）。
    // 进程无法自我调高该参数，这里只做告警（启动日志 + 读取 run logs 中的环境信息），
    // 前端据服务日志的 ENOSPC 特征给出「调高 fs.inotify.max_user_watches」的针对性提示。
    #[cfg(unix)]
    warn_if_inotify_watch_limit_low();

    // Windows：剥离历史遗留的 `dsh-win-terminal-inspector` 注入行（幂等，官方核心
    // 自 0.1.0-rc.8 起内置 inspector）。最佳努力：失败只告警，不阻断启动。
    if let Err(e) = win_inspector::apply(&app_handle) {
        log::warn!("win32 legacy patch cleanup failed: {e}");
    }
    // renderer 的 SlotOutlet 一行导出补丁（dsh-tauri-ui 设置侧边栏依赖）：只补
    // 活动核心的 dsh-client-ui-renderer lib/client.js，已含导出即跳过（幂等；核心
    // 换版本后自动重打，上游官方导出后自动退休）。最佳努力：失败只告警，不阻断
    // 启动——未打补丁时插件侧降级，官方设置 dialog 照常工作，绝不白屏。
    if let Err(e) = crate::service::patch::renderer::apply(&app_handle) {
        log::warn!("renderer SlotOutlet patch failed: {e}");
    }
    // composer 可用性：官方 ConversationRoot 对「不属于任何工作区的空白会话」把
    // composer 换成「选择工作区」触发器（`inert` 只看 chipTitle，而 chipTitle 只来自
    // 工作区），于是 dsh-tauri-ui 的「未分组」新会话无法输入。补丁放宽该判定（会话已有
    // cwd 即不算 inert）并写入 `data-dsh-composer-cwd` 能力标记；标记缺失时插件侧按
    // 退级策略禁用「未分组」入口并告警。最佳努力且幂等：锚点缺失安全跳过。
    if let Err(e) = crate::service::patch::composer::apply(&app_handle) {
        log::warn!("composer workspace-less patch failed: {e}");
    }
    if let Err(e) = crate::service::patch::mobile_composer::apply(&app_handle) {
        log::warn!("mobile composer patch failed: {e}");
    }
    // Expose an id-based SessionStore.remove facade so plugins can perform a
    // real in-memory teardown instead of leaving deleted sessions ungrouped.
    if let Err(e) = crate::service::patch::session::apply(&app_handle) {
        log::warn!("SessionStore.remove patch failed: {e}");
    }
    // OpenCode Go 需要稳定的会话 ID 头，否则返回 400 MissingSessionID；上游 pi-ai
    // 适配器把 sessionId 只透传给 SDK、不落成请求头，这里补上原生会话头，并限定到
    // OpenCode 路由（provider id 前缀或生效 baseUrl 主机为 opencode.ai），其它 provider
    // 的请求头保持不变。最佳努力且幂等：目标已含标记或锚点缺失时 patch_dsh 安全跳过。
    if let Err(e) = crate::service::patch::llm_session::apply(&app_handle) {
        log::warn!("pi-ai session header patch failed: {e}");
    }
    // Codex 系端点把思维链写在正文里（`<thinking>…</thinking>`），pi-ai 的
    // openai-completions 适配器只认识结构化推理字段，思考便混进回答正文。补丁在
    // 消息开头的围栏处把这段文本改道到 thinking 事件，harness 侧按 reasoning 块落库。
    // 最佳努力且幂等：目标已含标记或锚点缺失时 patch_dsh 安全跳过。
    if let Err(e) = crate::service::patch::pi_ai_thinking::apply(&app_handle) {
        log::warn!("pi-ai thinking-as-text patch failed: {e}");
    }
    // WKWebView 点击 `<button>` 不转移焦点：模型座位的 portal 菜单在 mousedown 阶段收到
    // `relatedTarget` 为 null 的 blur 就直接 close()，菜单在 click 之前卸载，鼠标选择
    // 模型 / 推理等级变成空操作（键盘 Enter 正常、浏览器正常）。补丁放行该 blur，菜单外的
    // 点击仍由组件自身的文档级 mousedown 处理器关闭。最佳努力且幂等：锚点缺失时安全跳过。
    if let Err(e) = crate::service::patch::model_selection::apply(&app_handle) {
        log::warn!("model selection mouse click patch failed: {e}");
    }
    // worktree 会话以隔离 cwd 执行，但产品归属仍是源 Workspace；放宽上游显式
    // attach 的 cwd 相等约束，其他 cwd 有效性校验保持不变。最佳努力且幂等。
    if let Err(e) = crate::service::patch::workspace::apply(&app_handle) {
        log::warn!("workspace worktree membership patch failed: {e}");
    }
    // 0.1.6-alpha.1 起 dsh-client-ui-workspace 的浏览视图 store 去掉了
    // `sessionUpdatedAtByAccount`（persist key 仍是 dsh.workspace.view.v5）：先跑过新核心
    // 再切回 0.1.5-rc.1 / rc.2 时，旧核心的 retainAccountKeys 会
    // Object.entries(undefined) 抛错，sidebar.workspaces 整条槽崩掉且不会自愈。
    // 补丁把该 action 的取值放宽为 `?? {}`，逐条独立判定：0.1.7 起上游第三条改成了
    // `delete`，前两条的放宽仍然生效；只有该 action 被整体改写才安全跳过。
    if let Err(e) = crate::service::patch::workspace_view::apply(&app_handle) {
        log::warn!("workspace view state patch failed: {e}");
    }
    // 内置插件（dsh-tauri-*）只在壳的插件弹窗里可见：官方侧边栏 Plugins 页与插件市场
    // 都按各自的硬编码内置/inbox 名单判断 bundle 归属，上游没有可配置开关，因此对这两个
    // 前端做幂等补丁。最佳努力且幂等：锚点缺失（上游改写布局）时安全跳过。
    if let Err(e) = crate::service::patch::plugin_visibility::apply(&app_handle) {
        log::warn!("plugin visibility patch failed: {e}");
    }
    // 桌面载体鉴权补丁：随行核心把内置 Web 门禁在「每进程启动 token」之后，而无 token
    // 的内嵌 iframe 与 `is_dsh_running` 的就绪探测都需要裸 `GET /`。补齐上游缺失的
    // 「桌面端鉴权补丁」，让本地载体免 token 访问（信任边界见 service::patch::browser_auth）。
    // 最佳努力且幂等：目标已打过或锚点缺失时安全跳过。
    if let Err(e) = crate::service::patch::browser_auth::apply(&app_handle) {
        log::warn!("browser auth carrier patch failed: {e}");
    }
    mark_phase("core_patches", &mut phase_started);
    // 预防性处理：pnpm 在无 TTY 环境（dsh-market 等子进程）下重装/更新插件时，
    // 清理/重建 node_modules 会触发交互确认并因无 TTY 直接中止
    // （ERR_PNPM_ABORTED_REMOVE_MODULES_DIR_NO_TTY），表现为插件更新失败。
    // 启动时确保 profile 的 .npmrc 写入 confirmModulesPurge=false（幂等、保留
    // 已有配置）。最佳努力：失败只告警，不阻断启动。
    if let Err(e) = crate::service::plugin::ensure_profile_npmrc(&app_handle) {
        log::warn!("ensure profile .npmrc failed: {e}");
    }
    // 弃用插件自动卸载：`manifest.jsonc` 的 `plugins.depercated` 登记的社区插件若已安装，启动时
    // 自动移除（避免残留插件继续在 profile 里加载、甚至导致启动失败）。最佳努力：
    // 失败只告警，不阻断启动。
    if let Err(e) = crate::service::plugin::uninstall_deprecated_plugins(&app_handle).await {
        log::warn!("uninstall deprecated plugins failed: {e}");
    }
    mark_phase("deprecated_plugins", &mut phase_started);
    // 内置插件自愈：随包分发的内置插件（dsh-tauri 等）必须在服务进程加载插件
    // 前就绪——核对「已安装 + 安装路径指向当前捆绑目录」，未安装、路径不正确
    // 或用户卸载后重启，一律强制重装（见 service::plugin::internal）。最佳
    // 努力：失败只告警，不阻断启动（核心功能缺失是发布缺陷，由 build:plugins 报错）。
    if let Err(e) = crate::service::plugin::ensure_internal_plugins(&app_handle).await {
        log::warn!("ensure internal plugins failed: {e}");
    }
    mark_phase("ensure_internal_plugins", &mut phase_started);
    // 预装插件完整性自检：清单引用的预装插件若在 node_modules 缺失产物，服务
    // 启动时 loader 会对每个缺失插件抛 ERR_MODULE_NOT_FOUND 而整体失败（issue
    // #90，日志特征 `Cannot find package`）。用 `pnpm install` 以现有 manifest +
    // lockfile 为准重建依赖图修复；修复失败只告警并给缺失插件记录错误标记
    // （启动失败场景由前端 recovery 对话框兜底，见 service::plugin::recovery）。
    if let Err(e) = crate::service::plugin::ensure_preset_plugins(&app_handle).await {
        log::warn!("ensure preset plugins failed: {e}");
    }
    mark_phase("ensure_preset_plugins", &mut phase_started);
    // 插件自愈（内置插件重装 / 预装插件完整性自检）可能刚把插件市场装进档案，而上一轮补丁
    // 执行时它还不存在、已被安全跳过；自愈完成后按需重打一次（逐名字判定，已登记则跳过）。
    if let Err(e) = crate::service::patch::plugin_visibility::apply(&app_handle) {
        log::warn!("plugin visibility patch after plugin self-healing failed: {e}");
    }
    // 预打包核心运行时自愈：把 app 内置插件与 profile 插件入口链接进活动核心的
    // node_modules（dsh 的 loader 以核心根为裸包解析根），并核验/修复 sharp/koffi
    // 原生可选依赖。只作用于 CoreSource::App，本地核心由用户自行管理。dsh 在缺失
    // 这些入口或原生依赖时无法启动，因此失败直接阻断本次 launch（前端展示可恢复
    // 错误），而不是带着必然失败的核心继续 spawn。
    if let Err(e) = crate::service::core::prepare_active_runtime(&app_handle).await {
        log::error!("prepare active core runtime failed: {e}");
        return Err(e);
    }
    mark_phase("prepare_active_runtime", &mut phase_started);
    // prepare 可能因核心原生模块的 ABI 与本地 node 不匹配而改用捆绑运行时
    // （issue #441），此时必须重新解析：下面的 DSH_NODE 注入与 PATH 前置都以
    // 这里的结果为准，否则子进程仍会用那个加载不了原生模块的本地 node。
    let node_binary_path = config::get_node_binary_path(&app_handle);
    if !node_binary_path.exists() {
        log::error!("Node.js runtime resolved for launch is missing");
        return Err(format!(
            "NODE_NOT_FOUND: Node.js runtime is missing: {}",
            node_binary_path.display()
        ));
    }
    let mut envs: HashMap<String, String> = HashMap::new();
    envs.insert(
        "DSH_HOME".to_string(),
        dsh_home.to_string_lossy().into_owned(),
    );
    envs.insert("DSH_TELEMETRY_DISABLED".to_string(), "1".to_string());
    envs.insert("NO_COLOR".to_string(), "1".to_string());
    envs.insert("DSH_WEB_PORT".to_string(), setting.port.to_string());
    // 把服务实际使用的 node 路径显式交给子进程（pnpm/dsh shim 的 DSH_NODE
    // 优先）：市场（dsh-market）等子进程经 PATH 解析 node 可能与桌面端预检
    // 不一致（相对 PATH 条目 / junction / 子进程 PATH 布局差异），导致 pnpm
    // shim 报 "Node.js runtime not found"（issue #121，与 build_plugin_envs
    // 的注入保持一致）。先规范化为绝对路径：相对路径在子进程 CWD 下会解析
    // 到错误位置；已存在（上面校验过）的 node 可安全 canonicalize。用
    // dunce::canonicalize 而不是 std::fs::canonicalize：后者在 Windows 上会
    // 返回 `\\?\` verbatim 前缀，cmd.exe 无法直接启动这种路径，导致 pnpm/dsh
    // shim 报 "The system cannot find the path specified."。
    let node_abs =
        dunce::canonicalize(&node_binary_path).unwrap_or_else(|_| node_binary_path.clone());
    envs.insert(
        "DSH_NODE".to_string(),
        node_abs.to_string_lossy().into_owned(),
    );

    // 扩展 PATH，让 dsh 及其子进程能找到 node 与桌面端自动配置的 Git；Windows
    // 上再注入 Git Bash 的 bin 目录：persistent bash（--noprofile --norc）不执行
    // profile 脚本、PATH
    // 完全继承服务进程，若不含 Git 的 usr/bin，ls/sed/find 等 coreutils 全会
    // `command not found`（MSYS 运行时在部分环境下不会自动补 /usr/bin）。
    // 前置应用自身的 shim 目录，使市场（dsh-market）及其子进程通过名字解析的
    // `pnpm`/`dsh` 都命中桌面端 shim，从而受桌面端 pnpm 选版策略管辖
    // （轻量缓解，issue #69 系列）。
    if let Some(node_dir) = node_binary_path.parent() {
        if let Some(existing_path) = std::env::var_os("PATH") {
            let git_dirs = win_inspector::git_bash_bin_dirs();
            // 只打印注入的前缀目录，完整 PATH 太长会刷屏
            for dir in &git_dirs {
                log::debug!("harness service PATH prepend: {}", dir.to_string_lossy());
            }
            let mut paths = vec![crate::service::cli::get_bin_dir(&app_handle)];
            paths.push(node_dir.to_path_buf());
            if let Some(git_dir) = config::get_git_cmd_dir(&app_handle) {
                log::debug!(
                    "harness service Git PATH prepend: {}",
                    git_dir.to_string_lossy()
                );
                paths.push(git_dir);
            }
            paths.extend(git_dirs);
            paths.extend(std::env::split_paths(&existing_path));
            if let Ok(new_path) = std::env::join_paths(paths) {
                envs.insert("PATH".to_string(), new_path.to_string_lossy().into_owned());
            }
        }
    }

    // GUI 进程可能启动在 pnpm 安装之前，继承的 PATH 因而没有 npm 全局目录。
    // 直接注入探测到的绝对路径，避免 dsh-market 的 pnpm --version 落到自身 shim
    // 后又因 PATH 看不到真正的 pnpm（issue #139）。
    if let Some(user_pnpm) = crate::service::cli::find_user_pnpm(&app_handle) {
        // Unix mise shim 依赖调用路径中的 argv[0]；只做字面绝对化，不能解析
        // `pnpm -> mise` 链接。Windows 仍由同一辅助函数处理连接点与 `\\?\`。
        if let Some(pnpm_value) = crate::service::cli::pnpm_env_value(
            &user_pnpm,
            &crate::service::cli::get_bin_dir(&app_handle),
        ) {
            envs.insert("DSH_PNPM".to_string(), pnpm_value);
        }
    }

    // 让市场子进程的 pnpm 与桌面端同一套受控策略（store 主版本感知、避免落到系统
    // homebrew pnpm）。与插件安装路径的 ensure_pnpm 版本感知一致，但启动阶段绝不
    // 触发下载；捆绑版未安装或与 store 不匹配时不注入（交由用户 pnpm）。
    // 最佳努力：失败只告警，不阻断启动。
    if crate::service::plugin::harness_prefer_bundled_pnpm(&app_handle) {
        envs.insert("DSH_PREFER_BUNDLED_PNPM".to_string(), "1".to_string());
    }

    // 内嵌 WebView 是 `tauri.localhost` 下的跨源沙箱 iframe，`SameSite=Strict` 的
    // browser-session Cookie 不会被携带。载体标记交给 dsh-tauri 插件（载体鉴权适配）：
    // 只有该标记在场时它才覆写 connection 的鉴权闸门，因此同一 profile 下独立运行
    // 的 `dsh web` 不受影响（取代原先对核心 JS 打的 `--skip-auth` 磁盘补丁）。
    envs.insert("DSH_TAURI_EMBEDDED".to_string(), "1".to_string());

    // 日志文件（前端日志面板读取）。
    // 每次真实启动前轮转：只保留最近 3 次启动的日志，旧文件后退为
    // `dsh-web.log.1` / `dsh-web.log.2`，避免单文件随多次启动无限增长。
    let log_path = config::get_service_log_path(&app_handle);
    fs::create_dir_all(log_path.parent().unwrap_or(std::path::Path::new(".")))
        .map_err(|e| format!("LOG_DIR_MKDIR_FAILED: create log dir failed: {e}"))?;
    rotate_service_log(&log_path, 3);

    // `dsh web` 默认在系统浏览器打开 UI；桌面端内嵌 WebView，不需要浏览器，
    // 追加 `--no-open` 关闭。该标志自 0.1.0-rc.8 起提供，全部受支持核心（≥
    // 0.1.5-rc.1）均已具备，无需按版本判定。

    // 补丁层悬空 insert 预检：手写的 `insert` 条目在包被卸载（市场会拒绝卸载
    // 「仍被用户补丁引用」的插件，用户于是改走手工删依赖 / pnpm remove）或本地
    // `link:` 源被删后仍留在补丁层里，loader 会在 import 时抛 ERR_MODULE_NOT_FOUND，
    // 让整棵插件树加载失败——应用彻底起不来，用户只看到一坨 Node 堆栈。上游契约
    // 是「补丁文件存在却应用不了就大声失败」，这里不改变契约，只把同一结果提前成
    // 一条可操作的错误（哪个文件、哪一行、哪个包），错误页据此给出「移除悬空条目」
    // 的一键恢复。必须在所有插件自愈之后：那些步骤会改变安装状态。
    if let Err(e) = crate::service::plugin::preflight_active_patch_entries(&app_handle) {
        log::error!("patch layer entry preflight failed: {e}");
        return Err(e);
    }
    mark_phase("patch_entry_preflight", &mut phase_started);

    let node_options = std::env::var("NODE_OPTIONS").ok();
    let heap_mb = super::heap::resolve_heap_limit_mb(
        setting.harness_max_heap_mb,
        node_options.as_deref(),
        super::heap::physical_memory_mb(),
    );
    match heap_mb {
        Some(mb) => log::info!("Starting Harness process with --max-old-space-size={mb}"),
        None => log::info!("Starting Harness process with Node default or inherited heap options"),
    }

    // dsh 的 Loader 在插件 dispose 时会把组合后的整棵 entry 树回写进
    // `cordis.yml`（dsh-app-boot：plugin self-disposing persists the current
    // tree）。上一轮被杀/崩溃的 dsh 若在「新进程 prepareProfile 重置之后、
    // Include 读取之前」完成回写，新 boot 会读到已含 bundle 组合行的文件，
    // 再叠加同一批 patch → duplicate loader entry（本会话实测特征
    // `duplicate loader entry id: dsh-tauri-worktree`）。spawn 前最后一刻重置
    // profile 根关闭常见窗口；回写恰好落在探测窗口内的残余竞态由下方
    // Windows 分支的「早期退出重试」兜底。
    reset_active_profile_root(&app_handle);

    // Windows 打包版是 GUI 进程（没有控制台）。直接以 CREATE_NO_WINDOW 启动
    // node 会让 dsh 派生的子进程各自新建可见控制台窗口（频繁闪烁 cmd 黑窗），
    // 因此 Windows 上改用“隐藏控制台”方式启动，见 win_spawn 模块。
    let active_profile = crate::service::profile::active_profile(&app_handle);
    let app_core_dir = config::get_dsh_install_path(&app_handle);
    let core_dir = if dsh_binary_path == config::get_dsh_binary_path(&app_handle) {
        app_core_dir
    } else {
        dsh_binary_path
            .parent()
            .and_then(std::path::Path::parent)
            .map(std::path::Path::to_path_buf)
            .unwrap_or(app_core_dir)
    };
    mark_phase("pre_spawn_setup", &mut phase_started);
    let spawn_result: SpawnResult = {
        #[cfg(windows)]
        {
            use std::io::{BufReader, Read};
            use windows_sys::Win32::Foundation::{CloseHandle, HANDLE, WAIT_TIMEOUT};
            use windows_sys::Win32::System::Threading::{
                GetExitCodeProcess, WaitForSingleObject, INFINITE,
            };

            let args = build_harness_args(&dsh_binary_path, active_profile.as_str(), setting.port, heap_mb);

            // 只负责 spawn 并返回管道/PID/句柄：探测与重试期间不登记、不挂
            // 监视线程——只有最终采用的那个进程才登记，否则旧监视线程会通过
            // `on_owned_process_exit` 把刚启动的新进程误当作已退出而回落状态。
            let spawn_harness =
                || -> std::io::Result<(std::fs::File, std::fs::File, u32, HANDLE)> {
                    super::win_spawn::spawn_with_hidden_console_owned(
                        &node_binary_path,
                        &args,
                        Some(&core_dir),
                        &envs,
                    )
                };

            // 早期退出重试：崩溃的上一轮 dsh 回写 `cordis.yml` 落在「新进程
            // prepareProfile 重置之后、Include 读取之前」时，新 boot 会把已含
            // bundle 组合行的 root 再叠加同一批 patch → `duplicate loader
            // entry`（实测 exit code 1）。spawn 前重置只覆盖常见窗口，这里在
            // spawn 后探测 ≤2.5s：命中签名则丢弃实例、重置 profile 根并重试
            //（最多 3 次，第二次 boot 基于干净状态必然成功）；仍在运行则视为
            // 健康立即放行登记。探测期间最长阻塞 2.5s，之后才返回给调用方。
            let mut attempt = 0u32;
            let mut outcome = spawn_harness();
            loop {
                attempt += 1;
                let (stdout, stderr, pid, handle) = match outcome {
                    Ok(spawned) => spawned,
                    Err(error) => {
                        // spawn 自身失败（非竞态）：保持 Err 交给下方 map 传播
                        outcome = Err(error);
                        break;
                    }
                };
                let wait = unsafe { WaitForSingleObject(handle, 2500) };
                if wait == WAIT_TIMEOUT {
                    // 健康：进程仍在运行，交给下方登记 + 监视线程。
                    outcome = Ok((stdout, stderr, pid, handle));
                    break;
                }
                // 已提前退出：读 stderr 判断是否命中竞态签名。
                let mut exit_code: u32 = 0;
                let got_exit_code = unsafe { GetExitCodeProcess(handle, &mut exit_code) } != 0;
                let mut stderr_text = String::new();
                let mut stderr_reader = BufReader::new(stderr);
                let _ = Read::read_to_string(&mut stderr_reader, &mut stderr_text);
                let hit_duplicate =
                    got_exit_code && is_duplicate_loader_exit(exit_code, &stderr_text);
                if hit_duplicate && attempt < 3 {
                    // 丢弃首个失败实例：从未登记，句柄由本分支关闭（此时没有
                    // 监视线程，不存在重复 close）。
                    drop(stdout);
                    unsafe { CloseHandle(handle) };
                    log::warn!(
                        "DUPLICATE_LOADER_ENTRY: dsh exited early with duplicate loader entry \
                         (pid={pid}, code={exit_code}); resetting profile root and relaunching \
                         (attempt {attempt}/3)"
                    );
                    reset_active_profile_root(&app_handle);
                    outcome = spawn_harness();
                    continue;
                }
                // 非签名提前退出或重试耗尽：走正常路径——已捕获的 stderr 补写
                // 日志避免失败原因丢失，句柄保持有效交给监视线程等待并关闭。
                for line in stderr_text.lines() {
                    log::warn!(target: "dsh", "{}", line);
                }
                outcome = Ok((stdout, stderr_reader.into_inner(), pid, handle));
                break;
            }

            outcome.map(|(stdout, stderr, pid, handle)| {
                // PID 与句柄作为整体一次登记，与退出清理（take 一并取出）配对
                let handle_value = handle as usize;
                set_owned_process_with_handle(pid, handle_value);
                let exit_app_handle = app_handle.clone();
                std::thread::spawn(move || unsafe {
                    let process_handle = handle_value as HANDLE;
                    WaitForSingleObject(process_handle, INFINITE);
                    // 进程确已退出：清空持有 PID 并把 Status 从 Running 回落为
                    // Stopped（原有实现只清 PID、状态永远停留在 Running）。
                    // 仅当该 PID 仍是当前登记才取出——旧监视线程不会误清新进程。
                    // take 返回值里的句柄由本线程负责关闭（不会与
                    // terminate_owned_process 重复 close——进程已 exit，
                    // 通常是本线程取走）。
                    let owned = on_owned_process_exit(&exit_app_handle, pid, |owned| {
                        let handle = owned.handle as HANDLE;
                        let mut exit_code: u32 = 0;
                        (GetExitCodeProcess(handle, &mut exit_code) != 0)
                            .then_some(i64::from(exit_code))
                    });
                    if let Some(owned) = owned {
                        let h = owned.handle as HANDLE;
                        CloseHandle(h);
                    }
                });
                (Some(stdout), Some(stderr), pid)
            })
        }
        #[cfg(not(windows))]
        {
            use std::os::unix::process::CommandExt;
            let mut cmd = Command::new(&node_binary_path);
            cmd.args(build_harness_args(&dsh_binary_path, active_profile.as_str(), setting.port, heap_mb));
            cmd.envs(&envs)
                .current_dir(&core_dir)
                // 核心修正：提供一个空的 stdin 防止 setRawMode 报错
                .stdin(Stdio::null())
                // 使用管道捕获输出，以便在子线程中读取
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                // 独立进程组让停止操作只影响 Harness 及其后代。
                .process_group(0);
            let mut attempt = 0u32;
            let mut child = 'attempts: loop {
                attempt += 1;
                match cmd.spawn() {
                    Ok(mut child) => {
                        let deadline =
                            std::time::Instant::now() + std::time::Duration::from_millis(2500);
                        loop {
                            match child.try_wait() {
                                Ok(Some(exit)) => {
                                    let mut stderr_text = String::new();
                                    if let Some(mut stderr) = child.stderr.take() {
                                        let _ = stderr.read_to_string(&mut stderr_text);
                                    }
                                    if exit.code() == Some(1)
                                        && stderr_text.contains("duplicate loader entry")
                                        && attempt < 3
                                    {
                                        log::warn!(
                                            "DUPLICATE_LOADER_ENTRY: dsh exited early with duplicate loader entry \
                                             (pid={}, code=1); resetting profile root and relaunching \
                                             (attempt {attempt}/3)",
                                            child.id()
                                        );
                                        reset_active_profile_root(&app_handle);
                                        cmd = Command::new(&node_binary_path);
                                        cmd.args(build_harness_args(&dsh_binary_path, active_profile.as_str(), setting.port, heap_mb));
                                        cmd.envs(&envs)
                                            .current_dir(&core_dir)
                                            .stdin(Stdio::null())
                                            .stdout(Stdio::piped())
                                            .stderr(Stdio::piped())
                                            .process_group(0);
                                        continue 'attempts;
                                    }
                                    for line in stderr_text.lines() {
                                        log::warn!(target: "dsh", "{}", line);
                                    }
                                    return Err(format!("Harness exited early: {exit}"));
                                }
                                Ok(None) if std::time::Instant::now() >= deadline => break,
                                Ok(None) => {
                                    std::thread::sleep(std::time::Duration::from_millis(50))
                                }
                                Err(error) => return Err(error.to_string()),
                            }
                        }
                        break child;
                    }
                    Err(error) => return Err(error.to_string()),
                }
            };
            let pid = child.id();
            let stdout = child.stdout.take();
            let stderr = child.stderr.take();
            set_owned_process(pid);
            let exit_app_handle = app_handle.clone();
            std::thread::spawn(move || {
                let code = child.wait().ok().and_then(|status| status.code());
                let _ = on_owned_process_exit(&exit_app_handle, pid, |_| code.map(i64::from));
            });
            Ok((stdout, stderr, pid))
        }
    };

    // 这一段包含 spawn、2.5s 存活探测与 `set_owned_process` 登记——登记写在 spawn 块
    // 内部，无法单独切分，所以不再为「登记」另打一个只量到一行 log 的点。
    mark_phase("spawn_probe_and_register", &mut phase_started);

    match spawn_result {
        Ok((stdout, stderr, pid)) => {
            log::info!(
                "Harness process started successfully: pid={pid}, port={}",
                setting.port
            );
            // 记录 PID+端口供下次启动清扫崩溃残留的孤儿实例（见 sweep_orphan_harness）
            persist_harness_pid(&app_handle, pid, setting.port);
            spawn_output_readers(stdout, stderr, log_path);
            Ok(())
        }
        Err(e) => {
            log::error!("Failed to start process: {}", e);
            Err(format!("PROCESS_START_FAILED: {e}"))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::net::TcpListener;

    #[test]
    fn occupied_port_advances_to_a_free_port() {
        let mut checked = Vec::new();
        let selected = find_available_port_by(3080, |port| {
            checked.push(port);
            port < 3082
        })
        .expect("find next free port");

        assert_eq!(selected, 3082);
        assert_eq!(checked, vec![3080, 3081, 3082]);
    }

    #[test]
    fn occupied_port_reports_exhaustion_at_max_port() {
        let error = find_available_port_by(u16::MAX, |_| true).expect_err("port exhaustion");
        assert!(error.starts_with("PORT_EXHAUSTED:"));
    }

    /// 模拟“上个会话残留进程刚被杀、端口仍在释放”的场景：先占用端口，随后在
    /// 另一线程释放。验证 `wait_for_port_release` 在端口回落后立即返回，而不是
    /// 等到完整等待窗口——这正是避免端口永久顶高（dev 热更新下 3081→3082→…）
    /// 的关键行为。
    #[tokio::test]
    async fn wait_for_port_release_returns_shortly_after_port_is_released() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind held test port");
        let held = listener.local_addr().expect("read held port").port();

        // 端口此刻确实被占用（模拟残留进程仍在监听）
        assert!(is_port_in_use(held));
        let releaser = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(150));
            drop(listener);
        });

        let started = std::time::Instant::now();
        wait_for_port_release(held).await;
        // 端口 150ms 后释放 + 80ms 轮询间隔，应远小于 1.5s 等待上限
        assert!(
            started.elapsed() < std::time::Duration::from_millis(800),
            "wait_for_port_release should return shortly after the port is released, not wait the full window"
        );
        releaser.join().expect("port releaser thread");
    }

    /// 「duplicate loader entry」竞态签名的判定：只认 exit code 1 + stderr 含
    /// 该文本（实测失败日志：
    /// `Error: dsh: plugin tree failed to load: failed to apply loader entry
    /// include (cordis:include): duplicate loader entry id: dsh-tauri-worktree`）。
    #[cfg(windows)]
    #[test]
    fn duplicate_loader_exit_signature_matches_observed_error() {
        let stderr = "Error: dsh: plugin tree failed to load: failed to apply loader entry include (cordis:include): duplicate loader entry id: dsh-tauri-worktree\nTypeError: duplicate loader entry id: dsh-tauri-worktree\n    at EntryGroup.update (...)";
        assert!(is_duplicate_loader_exit(1, stderr));
        // 其他退出码、无关错误或没有该文本的启动失败不命中
        assert!(!is_duplicate_loader_exit(0, stderr));
        assert!(!is_duplicate_loader_exit(2, stderr));
        assert!(!is_duplicate_loader_exit(
            1,
            "Error: EADDRINUSE: address already in use"
        ));
        assert!(!is_duplicate_loader_exit(1, ""));
    }

    /// 端口自愈（issue #91）：自动避让递增遗留的非默认端口，在回落目标空闲时
    /// 回落到目标（默认端口或用户手动端口），回落目标被占时维持当前端口。
    #[test]
    fn heal_port_returns_target_when_free() {
        // 自动递增遗留 3084，默认 3080 空闲 → 回落默认端口
        assert_eq!(resolve_heal_port(3084, 3080, true), 3080);
        // 用户手动 9090 空闲 → 回落用户值
        assert_eq!(resolve_heal_port(9091, 9090, true), 9090);
    }

    #[test]
    fn heal_port_keeps_current_when_target_busy_or_aligned() {
        // 回落目标被占 → 维持当前端口（留给 find_available_port 逐级递增）
        assert_eq!(resolve_heal_port(3084, 3080, false), 3084);
        // 当前端口即回落目标（已是最优）→ 不变
        assert_eq!(resolve_heal_port(3080, 3080, true), 3080);
        assert_eq!(resolve_heal_port(3080, 3080, false), 3080);
    }
}

//! Harness 进程生命周期：本应用持有的根进程登记（PID + Windows 句柄成对存储）、
//! 启动守卫、进程树终止与退出状态回落，以及按 dsh 安装路径清扫历史残留的
//! 孤儿服务实例（Windows 仅清扫父进程已退出且入口路径匹配的服务）。

use crate::config;
use std::fs;
#[cfg(windows)]
use std::path::Path;
use std::process::Command;
#[cfg(windows)]
use std::process::Stdio;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use tauri::{AppHandle, Emitter};

use super::status;
use super::sweep::harness_pid_path;

/// 当前持有的 Harness 根进程意外退出时通知前端的专用事件。
pub(super) const HARNESS_PROCESS_EXITED_EVENT: &str = "harness-process-exited";

/// Harness 根进程退出事件载荷。退出码在 Unix 被信号终止或系统查询失败时为空。
#[derive(Clone, Debug, serde::Serialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub(super) struct HarnessProcessExitedPayload {
    pub(super) pid: u32,
    pub(super) exit_code: Option<i64>,
}

/// 启动守卫：并发调用 `launch` 时只允许一个真正拉起 dsh 进程
pub(crate) static LAUNCH_GUARD: AtomicBool = AtomicBool::new(false);

/// 当前进程内由桌面端创建的 Harness 根进程（PID + Windows 句柄）。
///
/// PID 与句柄装在同一把锁的可选值里：`take()` 一次性成对取出，保证
/// 「PID 清空」与「句柄关闭」之间不存在跨原子竞态（WARN-6）。历史上 PID/句柄
/// 分两个 `Atomic*` 存储，`stop` 读 PID 与监视线程清句柄之间有微窗口可能导致
/// 漏杀或重复 close。
#[derive(Clone, Copy)]
pub(super) struct OwnedProcess {
    pub(super) pid: u32,
    /// Windows 进程句柄（原始 HANDLE 转 usize 存储，避免 `*mut c_void` 非 Send）。
    /// 只在 Windows 存在；Unix 无句柄概念。
    #[cfg(windows)]
    pub(super) handle: usize,
}

fn owned_process_lock() -> &'static Mutex<Option<OwnedProcess>> {
    static OWNED_PROCESS: OnceLock<Mutex<Option<OwnedProcess>>> = OnceLock::new();
    OWNED_PROCESS.get_or_init(|| Mutex::new(None))
}

/// 记录新持有的 Harness 根进程（Unix，启动成功后调用）。
#[cfg(not(windows))]
pub(super) fn set_owned_process(pid: u32) {
    let mut guard = owned_process_lock()
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    *guard = Some(OwnedProcess { pid });
}

/// 若调用方 owns 该进程（Windows 额外存句柄），记录之。
#[cfg(windows)]
pub(super) fn set_owned_process_with_handle(pid: u32, handle: usize) {
    let mut guard = owned_process_lock()
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    *guard = Some(OwnedProcess { pid, handle });
}

/// 原子取出持有的进程（PID+句柄一起）。取走者负责关闭 Windows 句柄；
/// 无条件取出（停止/退出路径）。
fn take_owned_process() -> Option<OwnedProcess> {
    owned_process_lock()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .take()
}

/// 仅当当前持有进程的 PID 与 `pid` 匹配时才取出（成对 PID+句柄）。
///
/// 保留 base 代码 `compare_exchange(pid, 0)` 的防护语义：退出监视线程只能清掉
/// 属于自己那一条登记，绝不误取/误清「刚启动的新进程」的登记——否则会把它
/// 当作已退出而错误回落 Status，并把新进程的句柄误关（WARN-6 合并引入的回退）。
fn take_owned_process_if(pid: u32) -> Option<OwnedProcess> {
    let mut guard = owned_process_lock()
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    take_owned_process_if_matching(&mut guard, pid)
}

/// 纯函数部分：便于单测，不触碰全局状态。
fn take_owned_process_if_matching(
    owned: &mut Option<OwnedProcess>,
    pid: u32,
) -> Option<OwnedProcess> {
    if owned.as_ref().map(|p| p.pid) == Some(pid) {
        owned.take()
    } else {
        None
    }
}

pub(crate) struct LaunchGuard;

impl Drop for LaunchGuard {
    fn drop(&mut self) {
        LAUNCH_GUARD.store(false, Ordering::SeqCst);
    }
}

/// 核心目录操作互斥锁：统一串行化「切换目录」与「启动并登记进程」两个临界区。
///
/// 不能只用一个布尔守卫：两个并发切换可能互相覆盖/清除状态，且 launch 在检查
/// 守卫与登记进程之间仍存在窗口。使用同一把 Tokio mutex 后，切换从停服到目录
/// 互换完成、launch 从最终状态检查到进程登记均保持互斥，避免 Harness 进程在
/// `dependencies/dsh` 目录交换期间加载 DLL 并产生 Windows os error 32。
fn core_transition_lock() -> &'static Arc<tokio::sync::Mutex<()>> {
    static LOCK: OnceLock<Arc<tokio::sync::Mutex<()>>> = OnceLock::new();
    LOCK.get_or_init(|| Arc::new(tokio::sync::Mutex::new(())))
}

/// 获取核心目录操作互斥锁，最长等待 15 秒。
///
/// 调用方必须从获取锁开始，持续持有到目录切换完成或 Harness 进程登记完成；
/// RAII guard 会在所有成功/失败路径自动释放。超时必须失败返回，避免切换或启动
/// 卡死后永久阻塞后续所有核心操作。
pub async fn acquire_core_transition() -> Result<tokio::sync::OwnedMutexGuard<()>, String> {
    const CORE_TRANSITION_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(15);
    tokio::time::timeout(
        CORE_TRANSITION_TIMEOUT,
        Arc::clone(core_transition_lock()).lock_owned(),
    )
    .await
    .map_err(|error| {
        format!(
            "CORE_TRANSITION_TIMEOUT: timed out after {} seconds waiting for core transition lock: {error}",
            CORE_TRANSITION_TIMEOUT.as_secs()
        )
    })
}

/// 是否持有 Harness 进程。与其它访问器一致：锁被毒化（panic 残留）时取回
/// 毒化守卫继续读取，而不是把「已登记进程」误报为「无」。
pub fn has_owned_process() -> bool {
    owned_process_lock()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .is_some()
}

pub fn owned_process_pid() -> Option<u32> {
    owned_process_lock()
        .lock()
        .unwrap_or_else(|error| error.into_inner())
        .as_ref()
        .map(|process| process.pid)
}

/// 处理「持有的 dsh 进程退出」这一事实（由退出监视线程与健康检查 tick 共用）：
///
/// - 仅当退出的 PID 仍是当前登记的那个进程时才清空持有（`take_owned_process_if`
///   按 pid 匹配），PID/句柄作为整体成对取出——杜绝「读 PID」与「清句柄」
///   之间的跨原子竞态（WARN-6），也杜绝旧监视线程误清新启动进程的登记；
/// - 匹配成功后无条件回落到 Stopped——进程可能在 Starting 或 Running 阶段
///   退出，任何情况下都不能继续广播一个已经失效的运行状态（WARN-5）。
///
/// 返回被取出的进程记录（含 Windows 句柄），取到者负责 `CloseHandle`——保证
/// 「取走进程」与「关闭句柄」同属一个调用者，杜绝重复 close。幂等：多次调用
/// （tick 与监视线程并发）只会生效一次，后续调用返回 None。
pub(super) fn on_owned_process_exit(
    app_handle: &AppHandle,
    pid: u32,
    exit_code: impl FnOnce(&OwnedProcess) -> Option<i64>,
) -> Option<OwnedProcess> {
    let owned = take_owned_process_if(pid)?;
    // 必须在成功取走当前 PID 后才读取 Windows 句柄：正常停止会先取走并关闭
    // 句柄，旧监视线程不得再查询该句柄，更不得发送“意外退出”事件。
    let exit_code = exit_code(&owned);

    if let Some(code) = exit_code {
        log::warn!(
            "Owned Harness process {} exited with code {code}; resetting status to Stopped",
            owned.pid
        );
        // SIGABRT：V8 堆耗尽（`JavaScript heap out of memory`）是桌面端最常见的成因
        // （issue #699），补一条可检索的日志，便于在没有前端时定位。
        if code == 134 {
            log::warn!(
                "HARNESS_HEAP_OOM: Harness aborted (code 134 / SIGABRT); an exhausted V8 heap \
                 limit is the common cause — raise the service memory limit in Settings"
            );
        }
    } else {
        log::warn!(
            "Owned Harness process {} exited (exit code unavailable); resetting status to Stopped",
            owned.pid
        );
    }

    status::set_status(status::Status::Stopped);
    status::emit_status(app_handle);
    let payload = HarnessProcessExitedPayload {
        pid: owned.pid,
        exit_code,
    };
    if let Err(error) = app_handle.emit(HARNESS_PROCESS_EXITED_EVENT, payload) {
        log::warn!("Failed to emit Harness process exit event: {error}");
    }
    Some(owned)
}

/// 只结束本应用当前进程创建并仍持有的 Harness 进程树。
///
/// 返回是否真的结束了一个进程：调用方据此决定要不要等端口释放。没有持有进程时
/// 是纯 no-op，不该白等——退出与安装器路径都在用户可见的关键路径上。
fn terminate_owned_process() -> Result<bool, ()> {
    // 一次性取出 PID+句柄（成对），杜绝「PID 已清空/句柄未清」的漏杀窗口
    let Some(owned) = take_owned_process() else {
        return Ok(false);
    };

    #[cfg(windows)]
    {
        use windows_sys::Win32::Foundation::{CloseHandle, WAIT_OBJECT_0};
        use windows_sys::Win32::System::Threading::WaitForSingleObject;
        const WAIT_TIMEOUT_CODE: u32 = 0x0000_0102;
        let handle = owned.handle as windows_sys::Win32::Foundation::HANDLE;
        if handle.is_null() {
            return Ok(true);
        }
        // 真实句柄已结束说明 PID 可能已复用，此时绝不调用 taskkill。
        if unsafe { WaitForSingleObject(handle, 0) } != WAIT_TIMEOUT_CODE {
            unsafe { CloseHandle(handle) };
            return Ok(true);
        }
        kill_pid_tree(owned.pid);
        if unsafe { WaitForSingleObject(handle, 5_000) } != WAIT_OBJECT_0 {
            let mut guard = owned_process_lock()
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            if guard.is_none() {
                *guard = Some(owned);
            } else {
                unsafe { CloseHandle(handle) };
            }
            log::error!("Harness process {} is still running after stop", owned.pid);
            return Err(());
        }
        unsafe { CloseHandle(handle) };
    }

    #[cfg(unix)]
    {
        kill_pid_tree(owned.pid);
    }

    Ok(true)
}

/// 结束进程树（Windows `taskkill /PID <pid> /T /F`；Unix 负 PID 进程组，与
/// 启动时 `process_group(0)` 对应）。调用方需先确认 PID 确实指向目标进程。
pub(super) fn kill_pid_tree(pid: u32) {
    #[cfg(windows)]
    {
        let mut cmd = Command::new("taskkill");
        cmd.args(["/PID", &pid.to_string(), "/T", "/F"]);
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x08000000);
        cmd.stdout(Stdio::null());
        cmd.stderr(Stdio::null());
        match cmd.output() {
            Ok(output) if output.status.success() => {}
            Ok(output) => log::error!(
                "Failed to stop Harness process tree {pid}: taskkill exited with {}",
                output.status
            ),
            Err(e) => log::error!("Failed to stop Harness process tree {pid}: {e}"),
        }
    }

    #[cfg(unix)]
    {
        // Harness 根进程启动在独立进程组中，负 PID 只作用于该进程树；手动通过
        // CLI 拉起的外围 dsh 进程未必有独立进程组（组信号报错），此时回退直接
        // 杀 PID——PID 的归属已由调用方确认（路径匹配或 .harness.pid 双重确认），
        // 绝不会误杀未知进程。
        let group = format!("-{pid}");
        let group_term_ok = Command::new("kill")
            .args(["-TERM", "--", &group])
            .output()
            .map(|output| output.status.success())
            .unwrap_or(false);
        if !group_term_ok {
            let _ = Command::new("kill")
                .args(["-TERM", "--", &pid.to_string()])
                .output();
        }
        std::thread::sleep(std::time::Duration::from_millis(300));
        let group_kill_ok = Command::new("kill")
            .args(["-KILL", "--", &group])
            .output()
            .map(|output| output.status.success())
            .unwrap_or(false);
        if !group_kill_ok {
            let _ = Command::new("kill")
                .args(["-KILL", "--", &pid.to_string()])
                .output();
        }
    }
}

/// 解析 `ps -axo pid=,command=` 的一行：返回 `(PID, 命令行)`。
///
/// 输出形如 `   12345 node /path/to/bin.js --profile web ...`（PID 前可能有
/// 前导空格、行尾有换行）。PID 缺失或不可解析的行返回 None（跳过该行）。
#[cfg_attr(windows, allow(dead_code))] // 仅 Unix 清场分支与测试使用
fn parse_ps_line(line: &str) -> Option<(u32, &str)> {
    let trimmed = line.trim_start();
    let split = trimmed.find(|c: char| c.is_whitespace())?;
    let pid = trimmed[..split].trim().parse::<u32>().ok()?;
    Some((pid, trimmed[split..].trim_start()))
}

/// 判断命令行中是否包含一个完整参数。
///
/// `ps` 会把 argv 用空格拼成命令行，但不会给本身含空格的参数补引号，因此不能
/// 用 `split_whitespace` 还原参数。改为在原始命令行中匹配完整字符串，并校验
/// 前后为空白或行边界；这样 macOS 的 `Library/Application Support` 路径也能
/// 正确识别，同时不会把路径前缀相似的其他参数误判为目标。
#[cfg_attr(windows, allow(dead_code))] // 仅 Unix 清场分支与测试使用
fn command_line_has_argument(cmdline: &str, argument: &str) -> bool {
    if argument.is_empty() {
        return false;
    }

    cmdline.match_indices(argument).any(|(start, matched)| {
        let before_is_boundary = cmdline[..start]
            .chars()
            .next_back()
            .is_none_or(char::is_whitespace);
        let end = start + matched.len();
        let after_is_boundary = cmdline[end..]
            .chars()
            .next()
            .is_none_or(char::is_whitespace);
        before_is_boundary && after_is_boundary
    })
}

/// 判断一个参数是否紧跟在另一个完整参数之后。
#[cfg_attr(windows, allow(dead_code))] // 仅 Unix 清场分支与测试使用
fn command_line_has_argument_after(cmdline: &str, preceding: &str, argument: &str) -> bool {
    if preceding.is_empty() || argument.is_empty() {
        return false;
    }

    cmdline.match_indices(preceding).any(|(start, matched)| {
        let end = start + matched.len();
        let rest = cmdline[end..].trim_start_matches(char::is_whitespace);
        rest.strip_prefix(argument)
            .is_some_and(|tail| tail.chars().next().is_none_or(char::is_whitespace))
    })
}

#[cfg(windows)]
fn is_windows_harness_command_line(cmdline: &str, dsh_bin: &str) -> bool {
    let normalized = cmdline.replace('/', "\\");
    let path = dsh_bin.replace('/', "\\");
    // node 选项（`--max-old-space-size` 等）合法地夹在 node 与入口之间（issue #751）。
    let boundary = format!(
        r#"(?i)^\s*(?:"[^"]*\\node(?:\.exe)?"|[^\s"]*node(?:\.exe)?)(?:\s+-[^\s"]*)*\s+"?{}(?:"|\s|$)"#,
        regex::escape(&path)
    );
    regex::Regex::new(&boundary).is_ok_and(|pattern| pattern.is_match(&normalized))
        && is_harness_command_line(
            &normalized.replace('"', "").to_lowercase(),
            &path.to_lowercase(),
        )
        && command_line_has_argument(&normalized, "--no-open")
}

#[cfg(windows)]
fn terminate_stale_harness_processes_at(dsh_bin: &Path) {
    use std::os::windows::process::CommandExt;

    let Some(dsh_bin) = dsh_bin.to_str() else {
        return;
    };
    let script = "$ErrorActionPreference = 'Stop'; [Console]::OutputEncoding = [System.Text.Encoding]::UTF8; try { $all = Get-CimInstance Win32_Process; $byPid = @{}; foreach ($process in $all) { $byPid[$process.ProcessId] = $process }; foreach ($child in $all) { if ($child.Name -ne 'node.exe') { continue }; $parent = $byPid[$child.ParentProcessId]; if ($child.CreationDate -and (!$parent -or ($parent.CreationDate -and $parent.CreationDate.ToUniversalTime() -gt $child.CreationDate.ToUniversalTime()))) { [pscustomobject]@{ pid = $child.ProcessId; commandLine = $child.CommandLine; created = $child.CreationDate.ToFileTimeUtc() } | ConvertTo-Json -Compress } } } catch { Write-Error $_; exit 1 }";
    let output = match Command::new("powershell")
        .args(["-NoProfile", "-NonInteractive", "-Command", script])
        .creation_flags(0x08000000)
        .output()
    {
        Ok(output) if output.status.success() => output,
        Ok(output) => {
            log::warn!(
                "Failed to enumerate orphan Harness processes: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            return;
        }
        Err(error) => {
            log::warn!("Failed to enumerate orphan Harness processes: {error}");
            return;
        }
    };
    let owned_pid = owned_process_lock()
        .lock()
        .unwrap_or_else(|error| error.into_inner())
        .as_ref()
        .map(|process| process.pid);
    let mut found = 0;
    for (pid, created) in orphan_harness_pids(&output.stdout, dsh_bin, owned_pid) {
        if matches_process_creation(pid, created, || {
            log::warn!("Terminating orphan Harness service process {pid} (from dsh install dir)");
            kill_pid_tree(pid);
        }) {
            found += 1;
        }
    }
    if found > 0 {
        std::thread::sleep(std::time::Duration::from_millis(800));
    }
}

#[cfg(windows)]
fn matches_process_creation(pid: u32, created: u64, terminate: impl FnOnce()) -> bool {
    use windows_sys::Win32::Foundation::{CloseHandle, FILETIME, WAIT_TIMEOUT};
    use windows_sys::Win32::System::Threading::{
        GetProcessTimes, OpenProcess, WaitForSingleObject, PROCESS_QUERY_LIMITED_INFORMATION,
        PROCESS_SYNCHRONIZE,
    };

    let handle = unsafe {
        OpenProcess(
            PROCESS_QUERY_LIMITED_INFORMATION | PROCESS_SYNCHRONIZE,
            0,
            pid,
        )
    };
    if handle.is_null() {
        return false;
    }
    let mut creation = FILETIME {
        dwLowDateTime: 0,
        dwHighDateTime: 0,
    };
    let mut exit = creation;
    let mut kernel = creation;
    let mut user = creation;
    let matches = unsafe {
        GetProcessTimes(handle, &mut creation, &mut exit, &mut kernel, &mut user) != 0
            && WaitForSingleObject(handle, 0) == WAIT_TIMEOUT
            && (u64::from(creation.dwHighDateTime) << 32 | u64::from(creation.dwLowDateTime)) / 10
                == created / 10
    };
    if matches {
        terminate();
    }
    if !matches {
        log::warn!("Skipping orphan Harness process {pid}: creation time or process state changed (expected {created}, observed {})", u64::from(creation.dwHighDateTime) << 32 | u64::from(creation.dwLowDateTime));
    }
    unsafe { CloseHandle(handle) };
    matches
}

#[cfg(windows)]
fn orphan_harness_pids(output: &[u8], dsh_bin: &str, owned_pid: Option<u32>) -> Vec<(u32, u64)> {
    String::from_utf8_lossy(output)
        .lines()
        .filter_map(|line| {
            let process = serde_json::from_str::<serde_json::Value>(line).ok()?;
            let pid = u32::try_from(process.get("pid")?.as_u64()?).ok()?;
            let command = process.get("commandLine")?.as_str()?;
            let created = process.get("created")?.as_u64()?;
            (Some(pid) != owned_pid && is_windows_harness_command_line(command, dsh_bin))
                .then_some((pid, created))
        })
        .collect()
}

/// 判断命令行是否为「从本应用 dsh 安装目录启动的 Harness 服务」。
///
/// 除入口路径外同时核对桌面端服务启动参数，避免清扫时误伤用户并行执行的
/// `dsh plugin` 等短命令。
#[cfg_attr(windows, allow(dead_code))] // 仅 Unix 清场分支与测试使用
fn is_harness_command_line(cmdline: &str, dsh_bin: &str) -> bool {
    command_line_has_argument(cmdline, dsh_bin)
        && !command_line_has_argument_after(cmdline, dsh_bin, "plugin")
        && command_line_has_argument(cmdline, "--profile")
        && command_line_has_argument(cmdline, "--port")
}

/// 结束所有从本应用 dsh 安装目录启动的 Harness 服务进程（含历史崩溃残留的孤儿实例）。
///
/// 只停本应用当前持有的进程不够：`.harness.pid` 标记只记录最近一次会话的 PID，
/// 应用多次崩溃/强杀（任务管理器结束等）会遗留多个孤儿 dsh 进程、端口一路漂移
/// （3080→3081→…），`sweep_orphan_harness` 每次只能回收最近一个，更早的孤儿
/// 会持续占用 `dependencies/dsh` 目录的文件句柄（node 以该目录为 cwd 且模块
/// DLL 加载在内存），更新切换目录时触发 os error 32（INSTALL_BACKUP_FAILED）。
///
/// Windows 只结束入口路径精确匹配且父进程已退出的 node 服务；仍由另一个桌面实例
/// 持有的服务不做清扫。Unix 保持原有 release 路径匹配行为。
pub fn terminate_stale_harness_processes(app_handle: &tauri::AppHandle) {
    if crate::managed::enabled() {return;}
    #[cfg(windows)]
    terminate_stale_harness_processes_at(&config::get_dsh_binary_path(app_handle));
    #[cfg(not(windows))]
    {
        if cfg!(debug_assertions) {
            return;
        }
        // Unix 同样需要按路径清扫：打开中的文件允许重命名确实不阻塞更新切换，
        // 但崩溃/强杀残留的孤儿 dsh 实例会持续监听端口，下一次启动只能一路
        // 漂移端口（3080→3081→…）并被持久化，表现为「更新后端口递增」
        // （issue #91）。用 `ps -ww -axo pid=,command=` 枚举完整命令行（`-ww`
        // 防止 macOS 按终端宽度截断长路径），按参数边界匹配本应用 dsh 入口与
        // 服务参数，不会误杀用户其它 node/dsh 命令，因此可安全地全部结束。
        let dsh_bin = config::get_dsh_binary_path(app_handle);
        let Some(dsh_bin_str) = dsh_bin.to_str() else {
            return;
        };
        let Ok(output) = Command::new("ps")
            .args(["-ww", "-axo", "pid=,command="])
            .output()
        else {
            log::error!("Failed to enumerate stale Harness service processes");
            return;
        };
        let mut found = 0;
        for line in String::from_utf8_lossy(&output.stdout).lines() {
            let Some((pid, cmdline)) = parse_ps_line(line) else {
                continue;
            };
            if !is_harness_command_line(cmdline, dsh_bin_str) {
                continue;
            }
            found += 1;
            log::warn!("Terminating stale Harness service process {pid} (from dsh install dir)");
            kill_pid_tree(pid);
        }
        if found > 0 {
            // 与 stop() 同理：信号发完后 PID 回收与端口释放还有短暂滞后，
            // 让出一点时间避免紧随其后的启动探测撞上尚未释放的端口。
            std::thread::sleep(std::time::Duration::from_millis(800));
        }
    }
}

#[cfg(unix)]
pub(super) fn warn_if_inotify_watch_limit_low() {
    let Some(limit) = crate::config::linux_inotify_max_user_watches() else {
        return;
    };
    if limit < crate::config::MIN_INOTIFY_MAX_USER_WATCHES {
        log::warn!(
            "Linux inotify.max_user_watches is {} (below recommended {}); dsh web may crash with ENOSPC (issue #116). To fix, run `sudo sysctl fs.inotify.max_user_watches={}` and write the same value to /etc/sysctl.conf to persist.",
            limit,
            crate::config::MIN_INOTIFY_MAX_USER_WATCHES,
            crate::config::MIN_INOTIFY_MAX_USER_WATCHES,
        );
    }
}

/// 停止 Harness 服务
pub async fn stop(app_handle: tauri::AppHandle) -> Result<(), String> {
    log::info!("Stopping Harness service...");
    // 重置启动守卫，确保后续 launch 可以重新拉起；仅结束持有的根进程树。
    // 进程终止涉及 WaitForSingleObject（至多 5s）与 taskkill/kill 等同步阻塞
    // 调用，移出 Tokio 执行线程避免卡住其他并发任务（WARN-7/P2-#20）。
    LAUNCH_GUARD.store(false, Ordering::SeqCst);
    tauri::async_runtime::spawn_blocking(terminate_owned_process)
        .await
        .map_err(|e| format!("STOP_FAILED: {e}"))?
        .map_err(|()| "STOP_FAILED: Harness process did not stop".to_string())?;
    // 清理孤儿清扫标记：正常停止的实例不应被下次启动当作残留
    let _ = fs::remove_file(harness_pid_path(&app_handle));

    // 给系统一点时间释放端口 (重要！)
    tokio::time::sleep(std::time::Duration::from_millis(800)).await;

    status::set_status(status::Status::Stopped);
    status::emit_status(&app_handle);
    Ok(())
}

/// 交付安装包前的同步停服：结束持有的 Harness 进程树 → 等端口释放 → 清清扫标记。
///
/// 安装器（Windows 的 `CheckIfAppIsRunning` → taskkill、macOS 安装脚本的
/// `CheckIfAppIsRunning`）会强杀桌面端进程，让应用走不到正常退出路径；桌面端一旦
/// 先消失，它持有的 Harness 子进程就变成孤儿继续占着配置端口，更新后新实例启动
/// 撞上 EADDRINUSE（表现为「更新后进不去」）。因此**打开安装包之前**必须先停服，
/// 这是平台无关的要求，不能只在某一条调用路径上做。
///
/// 同步、可在退出路径调用（无 async 运行时依赖）：进程从 SIGKILL 返回那一刻已死，
/// 但内核回收监听套接字仍有短暂滞后，故结束过进程后补一次有界等待，让紧随其后的
/// 安装器/新实例看到端口已释放。没持有进程时不等待，避免在用户可见路径上白耗。
pub fn stop_for_installer(app_handle: &tauri::AppHandle) {
    if !matches!(terminate_owned_process(), Ok(true)) {
        return;
    }
    // 正常停止路径同样清理清扫标记（崩溃路径才需要下次启动清扫）
    let _ = fs::remove_file(harness_pid_path(app_handle));
    log::info!("Harness stopped and port released for installer handoff");
    std::thread::sleep(std::time::Duration::from_millis(800));
}

/// 应用退出时同步回收 Harness 进程。
///
/// 退出路径上不更新状态，只结束当前应用持有的 Harness 进程树（与安装器交接共用
/// [`stop_for_installer`]，保证两条路径行为一致）。
pub fn stop_on_exit(app_handle: &tauri::AppHandle) {
    stop_for_installer(app_handle);
}

#[cfg(test)]
mod tests {
    use super::*;

    /// 构造一个测试用 `OwnedProcess`（跨平台处理 Windows 句柄字段）。
    #[cfg(windows)]
    fn test_owned(pid: u32) -> OwnedProcess {
        OwnedProcess { pid, handle: 0 }
    }
    #[cfg(not(windows))]
    fn test_owned(pid: u32) -> OwnedProcess {
        OwnedProcess { pid }
    }

    /// 退出监视线程只能清掉「与自己 PID 匹配」的登记，不许误清刚启动的新进程，
    /// 也不许重复取出（幂等）。回归 WARN-6 合并引入的回退。
    #[test]
    fn owned_process_take_if_only_matches_pid() {
        // 匹配的 PID 才可取出，且取走后槽清空
        let mut slot = Some(test_owned(42));
        let taken = take_owned_process_if_matching(&mut slot, 42);
        assert_eq!(taken.map(|p| p.pid), Some(42));
        assert!(slot.is_none());

        // PID 不匹配（旧进程 41 退出）时禁止取出/清空新进程（新进程 42）
        let mut slot = Some(test_owned(42));
        let taken = take_owned_process_if_matching(&mut slot, 41);
        assert!(taken.is_none());
        assert_eq!(slot.as_ref().map(|p| p.pid), Some(42));

        // 幂等：已清空后再次取出返回 None
        let mut slot: Option<OwnedProcess> = None;
        assert!(take_owned_process_if_matching(&mut slot, 42).is_none());
    }

